window.QUESTIONS_COURS = {"securite":[{"sid":"c:s-exam-01","mod":5692,"title":"Quelle moyenne générale faut-il obtenir pour être reçu à l'examen pratique du CCA ?","source":"cours","explanation":"<p>Il faut une moyenne générale d'au moins 12/20, avec la sécurité au coefficient 2 et le secourisme au coefficient 1.</p>","cref":[{"page":8,"printed":"1","quote":"supérieure ou égale à 12 sur 20 selon les coefficients suivants"}],"type":"mcq","input":"radio","options":[{"text":"10 sur 20","correct":false},{"text":"12 sur 20","correct":true},{"text":"14 sur 20","correct":false},{"text":"15 sur 20","correct":false}]},{"sid":"c:s-exam-02","mod":5692,"title":"Quelles notes sont éliminatoires à l'examen pratique ?","source":"cours","explanation":"<p>Moins de 6/20 en piscine est éliminatoire, tout comme une moyenne inférieure à 10/20 en sécurité OU en secourisme.</p>","cref":[{"page":8,"printed":"1","quote":"Toute note inférieure à 6 sur 20 en piscine est éliminatoire"},{"page":8,"printed":"1","quote":"Moyenne inférieure à 10 sur 20 en sécurité OU en secourisme est éliminatoire"}],"type":"mcq","input":"checkbox","options":[{"text":"Une note inférieure à 6/20 en piscine","correct":true},{"text":"Une moyenne inférieure à 10/20 en sécurité","correct":true},{"text":"Une moyenne inférieure à 10/20 en secourisme","correct":true},{"text":"Une note inférieure à 12/20 au feu-fumée","correct":false}]},{"sid":"c:s-exam-03","mod":5692,"title":"En combien de temps faut-il mettre un gilet de sauvetage dans l'eau lors de l'épreuve piscine ?","source":"cours","explanation":"<p>Épreuve piscine : mettre un gilet de sauvetage dans l'eau en moins de 30 secondes, tracter un passager sur 25 m, monter et faire monter un passager dans le canot.</p>","cref":[{"page":8,"printed":"1","quote":"Mettre un gilet de sauvetage dans l’eau en moins de 30 secondes"}],"type":"mcq","input":"radio","options":[{"text":"Moins de 15 secondes","correct":false},{"text":"Moins de 30 secondes","correct":true},{"text":"Moins de 45 secondes","correct":false},{"text":"Moins d'une minute","correct":false}]},{"sid":"c:s-exam-04","mod":5692,"title":"Que faut-il réaliser lors de l'épreuve du feu-fumée ?","source":"cours","explanation":"<p>Le feu-fumée : cagoule + extincteur, traversée de la cabine enfumée avec annonce au PA, puis extinction de 2 feux (bas et haut) sans tourner le dos.</p>","cref":[{"page":8,"printed":"1","quote":"Eteindre 2 feux (bas et haut) sans tourner le dos"}],"type":"mcq","input":"checkbox","options":[{"text":"S'équiper d'une cagoule de protection respiratoire et d'un extincteur","correct":true},{"text":"Traverser une cabine enfumée et faire une annonce au Public Address","correct":true},{"text":"Éteindre 2 feux (bas et haut) sans tourner le dos","correct":true},{"text":"Utiliser la hache pour ouvrir une cloison","correct":false}]},{"sid":"c:s-gil-01","mod":5681,"title":"Remets dans l'ordre l'utilisation du gilet double chambre réversible sur un ADULTE.","source":"cours","explanation":"<p>Chez l'adulte, on gonfle le gilet au seuil de porte, après avoir attaché et ajusté les sangles. On termine en enlevant les obturateurs de la pile hydroélectrique, reliée à la balise lumineuse.</p>","cref":[{"page":10,"printed":"3","quote":"Attacher et ajuster les sangles autour de la taille sur le devant"}],"type":"order","items":["Passer le gilet","Attacher et ajuster les sangles autour de la taille sur le devant","Gonfler le gilet au seuil de porte","Enlever les obturateurs de la pile hydroélectrique"]},{"sid":"c:s-gil-02","mod":5681,"title":"Remets dans l'ordre l'utilisation du gilet double chambre réversible sur un ENFANT.","source":"cours","explanation":"<p>Chez l'enfant, on gonfle AVANT de passer les sangles entre les jambes (une chambre peut suffire pour un enfant de petite taille), puis on confie l'enfant à un adulte.</p>","cref":[{"page":10,"printed":"3","quote":"Passer les sangles entre les jambes, attacher sur le devant et ajuster sans serrer"}],"type":"order","items":["Passer le gilet","Gonfler le gilet","Passer les sangles entre les jambes, attacher sur le devant et ajuster sans serrer","Enlever les obturateurs de la pile hydroélectrique","Confier l'enfant à un adulte"]},{"sid":"c:s-gil-03","mod":5681,"title":"Remets dans l'ordre l'utilisation du gilet MONO chambre sur un ENFANT.","source":"cours","explanation":"<p>Avec le gilet mono chambre, les sangles passent entre les jambes puis dans la bride dorsale ; on les croise devant et on les noue dans le dos.</p>","cref":[{"page":11,"printed":"4","quote":"Passer les sangles entre les jambes, puis dans la bride dorsale, croiser devant et nouer dans le dos"}],"type":"order","items":["Passer le gilet","Gonfler le gilet","Passer les sangles entre les jambes, puis dans la bride dorsale, croiser devant et nouer dans le dos","Enlever les obturateurs de la pile hydroélectrique","Confier l'enfant à un adulte"]},{"sid":"c:s-gil-04","mod":5681,"title":"Remets dans l'ordre l'utilisation du gilet bébé.","source":"cours","explanation":"<p>Gilet bébé : sangles ajustées sans serrer, gonflage, PUIS serrage des sangles. On confie le bébé à un adulte : 3 doigts dans la boucle de la cordelette, enroulée autour de la main.</p>","cref":[{"page":12,"printed":"5","quote":"Serrer les sangles"},{"page":12,"printed":"5","quote":"3 doigts dans la boucle et entourer autour de la main"}],"type":"order","items":["Passer le gilet et la sangle dorsale dans le dos et entre les jambes, ajuster sans serrer","Attacher la sangle latérale autour de la taille et ajuster sans serrer","Gonfler le gilet","Serrer les sangles","Enlever les obturateurs de la pile hydroélectrique","Confier le bébé à un adulte en lui expliquant comment tenir la cordelette de retenue"]},{"sid":"c:s-gil-05","mod":5681,"title":"Le gilet mono chambre est non-réversible : la cartouche de CO2 doit être à l'extérieur pour ne pas brûler le passager.","source":"cours","explanation":"<p>Vrai. Le gilet mono chambre est non-réversible : la cartouche de CO2 doit être à l'extérieur pour ne pas brûler le passager.</p>","cref":[{"page":11,"printed":"4","quote":"Non-réversible : la cartouche de CO2 doit être à l’extérieur pour ne pas brûler le passager"}],"type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}]},{"sid":"c:s-gil-06","mod":5681,"title":"De quoi se compose le système de gonflage semi-automatique d'une chambre de gilet ?","source":"cours","explanation":"<p>Chaque chambre a 2 systèmes de gonflage : un semi-automatique (cartouche de CO2, percuteur, poignée de percussion) ET un embout buccal, qui est un système à part.</p>","cref":[{"page":10,"printed":"3","quote":"1 semi-automatique : 1 cartouche de CO2, 1 percuteur, 1 poignée de percussion"}],"type":"mcq","input":"checkbox","options":[{"text":"1 cartouche de CO2","correct":true},{"text":"1 percuteur","correct":true},{"text":"1 poignée de percussion","correct":true},{"text":"1 embout buccal","correct":false},{"text":"1 bouteille d'oxygène","correct":false}]},{"sid":"c:s-gil-07","mod":5681,"title":"Comment fonctionne la balise lumineuse du gilet ?","source":"cours","explanation":"<p>Une fois les obturateurs retirés, l'eau rentre dans la pile hydroélectrique reliée à la balise lumineuse et crée de l'électricité.</p>","cref":[{"page":10,"printed":"3","quote":"l’eau rentre dans la pile et crée de l’électricité"}],"type":"mcq","input":"radio","options":[{"text":"Avec une pile hydroélectrique : l'eau rentre dans la pile et crée de l'électricité","correct":true},{"text":"Avec une pile au lithium activée par un interrupteur","correct":false},{"text":"Avec la cartouche de CO2","correct":false},{"text":"Elle s'allume au gonflage du gilet","correct":false}]},{"sid":"c:s-gil-08","mod":5681,"title":"Que faire si une cartouche de CO2 est défaillante au moment de gonfler le gilet ?","source":"cours","explanation":"<p>On utilise les embouts buccaux après avoir dévissé partiellement les cartouches défaillantes.</p>","cref":[{"page":10,"printed":"3","quote":"utiliser les embouts buccaux après avoir dévissé partiellement les cartouches défaillantes"}],"type":"mcq","input":"radio","options":[{"text":"Utiliser l'embout buccal après avoir dévissé partiellement la cartouche défaillante","correct":true},{"text":"Changer de gilet","correct":false},{"text":"Tirer plusieurs fois sur la poignée de percussion","correct":false},{"text":"Gonfler uniquement l'autre chambre et ne rien faire de plus","correct":false}]},{"sid":"c:s-gil-09","mod":5681,"title":"Sur un enfant de petite taille, une seule chambre du gilet double chambre peut suffire.","source":"cours","explanation":"<p>Vrai. Une chambre peut suffire si c'est un enfant de petite taille.</p>","cref":[{"page":10,"printed":"3","quote":"Une chambre peut suffire si c’est un enfant de petite taille"}],"type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}]},{"sid":"c:s-gil-10","mod":5681,"title":"Que faire si les sangles du gilet de l'enfant traînent par terre ?","source":"cours","explanation":"<p>Si les sangles traînent par terre, on les met dans l'encolure.</p>","cref":[{"page":10,"printed":"3","quote":"Si les sangles trainent par terre, les mettre dans l’encolure"}],"type":"mcq","input":"radio","options":[{"text":"Les mettre dans l'encolure","correct":true},{"text":"Les couper","correct":false},{"text":"Les nouer dans le dos","correct":false},{"text":"Les enrouler autour de la taille","correct":false}]},{"sid":"c:s-pos-01","mod":5682,"title":"Selon quels critères conseille-t-on une position de sécurité aux passagers ?","source":"cours","explanation":"<p>3 critères : l'espacement entre les rangées, le sens de la marche et l'état physique du passager.</p>","cref":[{"page":13,"printed":"6","quote":"Elles sont à conseiller aux passagers en fonction de 3 critères"}],"type":"mcq","input":"checkbox","options":[{"text":"L'espacement entre les rangées","correct":true},{"text":"Le sens de la marche","correct":true},{"text":"L'état physique du passager (femme enceinte, forte corpulence…)","correct":true},{"text":"La classe de voyage du passager","correct":false}]},{"sid":"c:s-pos-02","mod":5682,"title":"Comment se fait la position dressée face à la marche ?","source":"cours","explanation":"<p>Position dressée : mains sur les accoudoirs et menton dans la poitrine. La position groupée se fait avant-bras croisés sur les genoux et tête sur les avant-bras.</p>","cref":[{"page":13,"printed":"6","quote":"Position dressée face à la marche (1) : mains sur les accoudoirs et menton dans la poitrine"}],"type":"mcq","input":"radio","options":[{"text":"Mains sur les accoudoirs et menton dans la poitrine","correct":true},{"text":"Avant-bras croisés sur les genoux et tête sur les avant-bras","correct":false},{"text":"Mains derrière la nuque, tête contre le siège de devant","correct":false},{"text":"Bras croisés sur la poitrine, dos contre le dossier","correct":false}]},{"sid":"c:s-pos-03","mod":5682,"title":"Quelles sont les précautions communes à toutes les positions de sécurité ?","source":"cours","explanation":"<p>Précautions : ceinture attachée et ajustée au maximum, pieds et genoux serrés.</p>","cref":[{"page":13,"printed":"6","quote":"PRECAUTIONS : Ceinture attachée et ajustée au maximum. Pieds et genoux serrés."}],"type":"mcq","input":"radio","options":[{"text":"Ceinture attachée et ajustée au maximum, pieds et genoux serrés","correct":true},{"text":"Ceinture détachée pour pouvoir évacuer vite","correct":false},{"text":"Pieds écartés pour bien se caler","correct":false},{"text":"Tête relevée pour surveiller la cabine","correct":false}]},{"sid":"c:s-pos-04","mod":5682,"title":"Remets dans l'ordre la position de sécurité d'un passager avec un bébé.","source":"cours","explanation":"<p>Ceinture bébé passée dans celle du passager, bébé enroulé dans une couverture et placé latéralement, puis le passager protège sa tête et celle du bébé.</p>","cref":[{"page":13,"printed":"6","quote":"Passer la boucle de la ceinture bébé dans celle du passager et attacher"}],"type":"order","items":["Passer la boucle de la ceinture bébé dans celle du passager et attacher","Enrouler bébé dans une couverture et ajuster sa ceinture autour de la taille","Placer bébé latéralement, un bras sous sa tête, l'autre sous ses jambes","Le passager protège sa tête avec une main et celle du bébé avec l'autre main"]},{"sid":"c:s-pos-05","mod":5682,"title":"Un enfant dont les pieds ne touchent pas terre doit s'asseoir au bord du siège pour adopter la position de sécurité.","source":"cours","explanation":"<p>Faux. La position se fait assis au fond du siège même si les pieds ne touchent pas terre, pour que la ceinture maintienne correctement le passager.</p>","cref":[{"page":13,"printed":"6","quote":"La position de sécurité est à réaliser assis au fond du siège même si les pieds ne touchent pas terre"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:s-evm-01","mod":5683,"title":"Quelle est la particularité d'un toboggan non-convertible ?","source":"cours","explanation":"<p>Non-convertible : évacuation terrestre uniquement, les passagers sautent bras et jambes tendus en avant. C'est le convertible qui a des mâts, un container de survie et 2 tores.</p>","cref":[{"page":14,"printed":"7","quote":"Non-convertible : destiné à une évacuation terrestre uniquement"}],"type":"mcq","input":"radio","options":[{"text":"Il est destiné à une évacuation terrestre uniquement","correct":true},{"text":"Il peut servir en terrestre comme en maritime","correct":false},{"text":"Il est équipé de mâts et d'un container de survie","correct":false},{"text":"Il possède 2 tores superposés et indépendants","correct":false}]},{"sid":"c:s-evm-02","mod":5683,"title":"Le toboggan ne s'est pas gonflé. Que faites-vous ?","source":"cours","explanation":"<p>Si non gonflage, tirer sur la poignée de gonflage de secours. S'il reste inutilisable, rediriger les passagers.</p>","cref":[{"page":14,"printed":"7","quote":"Si non gonflage tirer sur la poignée de gonflage de secours"}],"type":"mcq","input":"radio","options":[{"text":"Tirer sur la poignée de gonflage de secours","correct":true},{"text":"Le désarmer et le gonfler à la main","correct":false},{"text":"Faire sauter les passagers quand même","correct":false},{"text":"Attendre qu'il se gonfle seul","correct":false}]},{"sid":"c:s-evm-03","mod":5683,"title":"En maritime, comment détache-t-on le toboggan convertible de l'avion ?","source":"cours","explanation":"<p>Principe de désolidarisation : sous le rabat au seuil de la porte, tirer la poignée qui provoque le délaçage du filin.</p>","cref":[{"page":14,"printed":"7","quote":"tirer la poignée qui provoque le délaçage du filin"}],"type":"mcq","input":"radio","options":[{"text":"En tirant la poignée sous le rabat au seuil de la porte, ce qui délace le filin","correct":true},{"text":"En coupant le filin avec le couteau insubmersible","correct":false},{"text":"En le désarmant avant l'ouverture","correct":false},{"text":"En tirant sur la poignée de gonflage de secours","correct":false}]},{"sid":"c:s-evm-04","mod":5683,"title":"Remets dans l'ordre les actions à mener avec le canot de sauvetage.","source":"cours","explanation":"<p>On désarme le toboggan, on attache le canot avant de le jeter, puis on percute le gonflage d'un coup sec sur le filin. Après vérification, on le rapproche, on obture la valve Venturi, puis on sèche et gonfle le fond.</p>","cref":[{"page":15,"printed":"8","quote":"Le jeter et tirer d’un coup sec sur le filin pour percuter le système de gonflage"}],"type":"order","items":["Désarmer le toboggan","Attacher le canot","Le jeter et tirer d'un coup sec sur le filin pour percuter le système de gonflage","Vérifier le gonflage","Le rapprocher pour une évacuation à pied sec","Obturer la valve Venturi grâce au bouchon","Séchage et gonflage du fond du canot"]},{"sid":"c:s-evm-05","mod":5683,"title":"À quoi sert la valve Venturi du canot ?","source":"cours","explanation":"<p>La valve Venturi est anti-retour : elle aspire l'air extérieur pour compléter le gonflage réalisé par la bouteille de CO2. On l'obture ensuite grâce au bouchon.</p>","cref":[{"page":15,"printed":"8","quote":"la valve Venturi est une valve anti-retour qui aspire l’air extérieur afin de compléter le gonflage réalisé par la bouteille de CO2"}],"type":"mcq","input":"radio","options":[{"text":"C'est une valve anti-retour qui aspire l'air extérieur pour compléter le gonflage par la bouteille de CO2","correct":true},{"text":"Elle sert à dégonfler le canot en fin de survie","correct":false},{"text":"Elle évacue l'eau du fond du canot","correct":false},{"text":"Elle permet de gonfler le toit","correct":false}]},{"sid":"c:s-evm-06","mod":5683,"title":"Le canot se déploie à l'envers. Que doit faire le passager requis ?","source":"cours","explanation":"<p>Le passager requis monte sur le tore, saisit la sangle de retournement et effectue un mouvement de bascule pour que le canot se retourne.</p>","cref":[{"page":15,"printed":"8","quote":"le passager requis devra monter sur le tore, saisir la sangle de retournement et effectuer un mouvement de bascule"}],"type":"mcq","input":"radio","options":[{"text":"Monter sur le tore, saisir la sangle de retournement et faire un mouvement de bascule","correct":true},{"text":"Couper le filin et en lancer un autre","correct":false},{"text":"Le dégonfler puis le regonfler","correct":false},{"text":"Attendre que les vagues le retournent","correct":false}]},{"sid":"c:s-evm-07","mod":5683,"title":"Quand l'armement du toboggan est-il réalisé ?","source":"cours","explanation":"<p>L'armement du toboggan est réalisé lors de la mise en route des moteurs. Lors de l'évacuation, on vérifie qu'il est bien armé.</p>","cref":[{"page":14,"printed":"7","quote":"Vérifier l’armement du toboggan (réalisé lors de la mise en route des moteurs)"}],"type":"mcq","input":"radio","options":[{"text":"Lors de la mise en route des moteurs","correct":true},{"text":"À l'ouverture de la porte","correct":false},{"text":"Juste avant l'évacuation","correct":false},{"text":"À l'embarquement des passagers","correct":false}]},{"sid":"c:s-eva-01","mod":5683,"title":"Qu'est-ce qu'une évacuation préparée ?","source":"cours","explanation":"<p>Préparée : le problème survient en vol, l'équipage a le temps de préparer la cabine et les passagers pendant le déroutement. Non préparée : décollage ou atterrissage, en zone aéroportuaire.</p>","cref":[{"page":16,"printed":"9","quote":"Le problème survient en vol, le temps du déroutement"}],"type":"mcq","input":"radio","options":[{"text":"Le problème survient en vol : le temps du déroutement, l'équipage a le temps de préparer la cabine et les passagers","correct":true},{"text":"Le problème survient au décollage ou à l'atterrissage","correct":false},{"text":"Une évacuation qui a lieu uniquement en zone aéroportuaire","correct":false},{"text":"Une évacuation où seuls les PNC sont préparés","correct":false}]},{"sid":"c:s-eva-02","mod":5683,"title":"Évacuation préparée en zone hostile ou maritime : que faut-il emporter ?","source":"cours","explanation":"<p>Hostile ou maritime : balise, torche, mégaphone, trousses médicales, vivres, eau et lot de survie selon la zone. À l'aéroport, seulement torche et mégaphone, car les secours sont proches.</p>","cref":[{"page":16,"printed":"9","quote":"Balise, torche, mégaphone, trousses médicales, vivres, eau et lot de survie selon la zone terrestre"}],"type":"mcq","input":"checkbox","options":[{"text":"Balise","correct":true},{"text":"Torche et mégaphone","correct":true},{"text":"Trousses médicales, vivres et eau","correct":true},{"text":"Lot de survie selon la zone terrestre","correct":true},{"text":"Les bagages des passagers","correct":false}]},{"sid":"c:s-eva-03","mod":5683,"title":"Évacuation préparée vers un aéroport : que faut-il emporter ?","source":"cours","explanation":"<p>À l'aéroport : torche et mégaphone, car les secours sont proches.</p>","cref":[{"page":16,"printed":"9","quote":"Aéroport : Torche, mégaphone car les secours sont proches"}],"type":"mcq","input":"radio","options":[{"text":"Torche et mégaphone","correct":true},{"text":"Balise et lot de survie","correct":false},{"text":"Trousses médicales et vivres","correct":false},{"text":"Rien, les secours s'en chargent","correct":false}]},{"sid":"c:s-eva-04","mod":5683,"title":"Quel est le rôle du passager requis lors d'une évacuation ?","source":"cours","explanation":"<p>Le passager requis bloque les passagers en attendant l'ouverture de la porte et porte assistance pendant l'évacuation.</p>","cref":[{"page":16,"printed":"9","quote":"bloquer les PAX en attendant l’ouverture de la porte et porter assistance aux PAX pendant l’évacuation"}],"type":"mcq","input":"checkbox","options":[{"text":"Bloquer les passagers en attendant l'ouverture de la porte","correct":true},{"text":"Porter assistance aux passagers pendant l'évacuation","correct":true},{"text":"Ouvrir la porte à la place du PNC","correct":false},{"text":"Récupérer la balise","correct":false}]},{"sid":"c:s-eva-05","mod":5683,"title":"Évacuation MARITIME : remets dans l'ordre les actions au seuil de porte puis dans l'embarcation.","source":"cours","explanation":"<p>On vérifie d'abord le seuil (si l'eau rentre, refermer et rediriger). Gilets gonflés au seuil, filin coupé au tranchet, on s'éloigne et on regroupe les embarcations, puis on organise la survie.</p>","cref":[{"page":16,"printed":"9","quote":"Vérifier que le seuil de la porte ne soit pas immergé"},{"page":16,"printed":"9","quote":"Couper le filin d’amarrage grâce au tranchet"}],"type":"order","items":["Vérifier que le seuil de la porte ne soit pas immergé","Gonfler le gilet au seuil de porte et enlever les objets pouvant blesser ou abîmer l'embarcation","Couper le filin d'amarrage grâce au tranchet","S'éloigner de l'épave et regrouper les embarcations avec la haussière","Monter le toit, sécher et gonfler le fond du canot, organiser la survie"]},{"sid":"c:s-eva-06","mod":5683,"title":"Le filin d'amarrage de l'embarcation possède un point de rupture de sécurité. De combien ?","source":"cours","explanation":"<p>On coupe le filin d'amarrage grâce au tranchet ; un point de rupture de 180 kg constitue une sécurité.</p>","cref":[{"page":16,"printed":"9","quote":"un point de rupture de 180kg constitue une sécurité"}],"type":"mcq","input":"radio","options":[{"text":"80 kg","correct":false},{"text":"120 kg","correct":false},{"text":"180 kg","correct":true},{"text":"250 kg","correct":false}]},{"sid":"c:s-eva-07","mod":5683,"title":"Évacuation maritime : l'eau rentre par la porte. Que faites-vous ?","source":"cours","explanation":"<p>Si l'eau rentre, on referme et on redirige les passagers.</p>","cref":[{"page":16,"printed":"9","quote":"Si l’eau rentre, refermer et rediriger les passagers"}],"type":"mcq","input":"radio","options":[{"text":"Refermer la porte et rediriger les passagers","correct":true},{"text":"Faire évacuer quand même, gilets gonflés","correct":false},{"text":"Jeter le canot par cette porte","correct":false},{"text":"Attendre que l'avion se stabilise","correct":false}]},{"sid":"c:s-eva-08","mod":5683,"title":"Évacuation terrestre : quel ordre donne-t-on aux passagers en bas du toboggan ?","source":"cours","explanation":"<p>En terrestre : sauter bras et jambes tendus en avant, puis s'éloigner rapidement dans une direction non dangereuse (zone d'explosion des pneus, moteurs, fuite de carburant…).</p>","cref":[{"page":16,"printed":"9","quote":"Sauter bras et jambes tendus en avant"}],"type":"mcq","input":"radio","options":[{"text":"S'éloigner rapidement dans une direction non dangereuse (pneus, moteurs, fuite de carburant…)","correct":true},{"text":"Rester groupés au pied du toboggan","correct":false},{"text":"Récupérer leurs bagages","correct":false},{"text":"Se placer sous l'aile","correct":false}]},{"sid":"c:s-eva-09","mod":5683,"title":"Évacuation NON préparée : quelles actions sont prévues ?","source":"cours","explanation":"<p>Évacuation non préparée (zone aéroportuaire) : mettre les gilets, désigner et briefer le passager requis, prendre torche et mégaphone, éloigner les passagers, puis les secours aéroportuaires prennent le relais.</p>","cref":[{"page":16,"printed":"9","quote":"Désignation et briefing du PAX requis"},{"page":16,"printed":"9","quote":"Eloigner les passagers et prise en charge des secours aéroportuaires"}],"type":"mcq","input":"checkbox","options":[{"text":"Mettre les gilets","correct":true},{"text":"Désigner et briefer le passager requis","correct":true},{"text":"Prendre torche et mégaphone","correct":true},{"text":"Éloigner les passagers ; prise en charge par les secours aéroportuaires","correct":true},{"text":"Emporter le lot de survie polaire","correct":false}]},{"sid":"c:s-elt-01","mod":5684,"title":"Sur combien de fréquences la balise ELT ADT 406S émet-elle simultanément ?","source":"cours","explanation":"<p>Elle émet SIMULTANÉMENT sur 3 fréquences : satellitaire 406 MHz, militaire 243 MHz et civile 121,5 MHz.</p>","cref":[{"page":20,"printed":"13","quote":"Elle émet SIMULTANEMENT sur 3 fréquences"}],"type":"mcq","input":"radio","options":[{"text":"1","correct":false},{"text":"2","correct":false},{"text":"3","correct":true},{"text":"4","correct":false}]},{"sid":"c:s-elt-02","mod":5684,"title":"Pendant combien de temps la balise émet-elle sur la fréquence satellitaire 406 MHz ?","source":"cours","explanation":"<p>406 MHz pendant 24 h. Les fréquences 243 MHz et 121,5 MHz émettent 48 h à -20 °C, et jusqu'à 60 h à +55 °C.</p>","cref":[{"page":20,"printed":"13","quote":"Satellitaire 406 MHz (Mégahertz) pendant 24 heures"}],"type":"mcq","input":"radio","options":[{"text":"24 heures","correct":true},{"text":"48 heures","correct":false},{"text":"60 heures","correct":false},{"text":"12 heures","correct":false}]},{"sid":"c:s-elt-03","mod":5684,"title":"Quelle est la précaution d'utilisation de la balise ELT ?","source":"cours","explanation":"<p>Précaution : visser l'antenne sur son embase. Le bouton TEST est réservé à la maintenance.</p>","cref":[{"page":20,"printed":"13","quote":"PRECAUTION Visser l’antenne sur son embase"}],"type":"mcq","input":"radio","options":[{"text":"Visser l'antenne sur son embase","correct":true},{"text":"Appuyer sur le bouton TEST","correct":false},{"text":"La garder au sec","correct":false},{"text":"La tenir à 45° au-dessus de la tête","correct":false}]},{"sid":"c:s-elt-04","mod":5684,"title":"Quelles sont les positions de l'interrupteur de la balise ELT ?","source":"cours","explanation":"<p>Interrupteur ON / OFF / ARMED. Attention : il faut soulever l'interrupteur pour le manipuler.</p>","cref":[{"page":20,"printed":"13","quote":"Un interrupteur avec les positions ON / OFF / ARMED"},{"page":21,"printed":"14","quote":"Soulever l’interrupteur lors de la manipulation"}],"type":"mcq","input":"radio","options":[{"text":"ON / OFF / ARMED","correct":true},{"text":"ON / OFF / TEST","correct":false},{"text":"ARMED / DISARMED","correct":false},{"text":"AUTO / MANUEL / OFF","correct":false}]},{"sid":"c:s-elt-05","mod":5684,"title":"Le bouton TEST de la balise ELT sert à vérifier son fonctionnement pendant la survie.","source":"cours","explanation":"<p>Faux. Le bouton TEST est réservé à la maintenance.</p>","cref":[{"page":20,"printed":"13","quote":"Un bouton TEST (réservé à la maintenance)"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:s-sky-01","mod":5685,"title":"Quelles sont les précautions d'utilisation du Sky Blazer ?","source":"cours","explanation":"<p>Sky Blazer : secours vus et/ou entendus, passagers et vent dans le dos, bras tendu à 45°. La condition « ET proches » concerne le stylo lance-fusées.</p>","cref":[{"page":22,"printed":"15","quote":"Passagers et vent dans le dos"}],"type":"mcq","input":"checkbox","options":[{"text":"Secours vus et/ou entendus","correct":true},{"text":"Passagers et vent dans le dos","correct":true},{"text":"Bras tendu à 45° au-dessus de la tête","correct":true},{"text":"Secours proches obligatoirement","correct":false}]},{"sid":"c:s-sky-02","mod":5685,"title":"Quelle est la portée en hauteur du Sky Blazer ?","source":"cours","explanation":"<p>Portée de 134 m de hauteur, visibilité jusqu'à 32 km par temps clair, 16 000 candelas.</p>","cref":[{"page":22,"printed":"15","quote":"Portée de 134 mètres de hauteur"}],"type":"mcq","input":"radio","options":[{"text":"30 mètres","correct":false},{"text":"134 mètres","correct":true},{"text":"300 mètres","correct":false},{"text":"32 km","correct":false}]},{"sid":"c:s-sky-03","mod":5685,"title":"Sky Blazer en MARITIME : remets dans l'ordre les étapes d'utilisation.","source":"cours","explanation":"<p>Le tube rouge se descend puis se verrouille, l'auriculaire se cale dans l'encoche, et on dévisse le capuchon pour libérer la chaînette. On tire bras tendu à 45° en tournant la tête, puis on refroidit le Sky Blazer.</p>","cref":[{"page":23,"printed":"16","quote":"Dévisser le capuchon du tube de lancement (rouge) pour libérer la chainette"}],"type":"order","items":["Se placer dos au vent, passagers derrière soi","À genoux dans l'embarcation, bras à l'extérieur","Tenir fermement le manchon (orange) en position verticale","Appuyer avec le pouce sur le haut du tube de lancement (rouge) pour le faire descendre, verrouiller en le tirant vers le bas","Caler l'auriculaire dans l'encoche du tube de lancement","Dévisser le capuchon du tube de lancement pour libérer la chaînette","Bras tendu à 45°, tourner la tête et tirer fermement la chaînette","Refroidir le Sky Blazer dans l'eau ou la terre"]},{"sid":"c:s-sky-04","mod":5685,"title":"Sky Blazer en TERRESTRE : où se placer ?","source":"cours","explanation":"<p>Terrestre : dos au vent, passagers derrière soi, dans un endroit dégagé et en hauteur, bras tendu à 45°.</p>","cref":[{"page":23,"printed":"16","quote":"Dans un endroit dégagé et en hauteur"}],"type":"mcq","input":"radio","options":[{"text":"Dans un endroit dégagé et en hauteur, dos au vent, passagers derrière soi","correct":true},{"text":"À l'abri, sous les arbres","correct":false},{"text":"Face au vent pour que la fusée monte plus haut","correct":false},{"text":"Au milieu des passagers","correct":false}]},{"sid":"c:s-sty-01","mod":5684,"title":"Quelle précaution distingue le stylo lance-fusées du Sky Blazer ?","source":"cours","explanation":"<p>Stylo : secours vus et/ou entendus ET proches. Ses fusées ont une hauteur de tir d'environ 30 m et une durée de combustion de 3 à 5 s.</p>","cref":[{"page":24,"printed":"17","quote":"Secours vus et/ou entendus ET proches"}],"type":"mcq","input":"radio","options":[{"text":"Les secours doivent être vus et/ou entendus ET proches","correct":true},{"text":"Il s'utilise vent de face","correct":false},{"text":"Il s'utilise uniquement de nuit","correct":false},{"text":"Il s'utilise bras le long du corps","correct":false}]},{"sid":"c:s-sty-02","mod":5684,"title":"Que contient le kit du stylo lance-fusées ?","source":"cours","explanation":"<p>2 stylos et 9 fusées rouges en forme étoilée, combustion de 3 à 5 s, hauteur de tir d'environ 30 m.</p>","cref":[{"page":24,"printed":"17","quote":"2 stylos + 9 fusées"}],"type":"mcq","input":"radio","options":[{"text":"2 stylos + 9 fusées","correct":true},{"text":"1 stylo + 6 fusées","correct":false},{"text":"2 stylos + 6 fusées","correct":false},{"text":"1 stylo + 9 fusées","correct":false}]},{"sid":"c:s-sty-03","mod":5684,"title":"Stylo lance-fusées : remets dans l'ordre la mise à feu (après s'être placé).","source":"cours","explanation":"<p>Percuteur au cran de sûreté, on visse la fusée sans passer la main au-dessus, puis cran d'armement et mise à feu en tournant la tête, sans accompagner le percuteur.</p>","cref":[{"page":24,"printed":"17","quote":"Tenir le stylo à la verticale dans une main, placer le percuteur dans le cran de sureté"}],"type":"order","items":["Tenir le stylo à la verticale dans une main, placer le percuteur dans le cran de sûreté","Enlever le bouchon protecteur du pas de vis de la fusée et la visser (sans passer la main au-dessus)","Déplacer le percuteur dans le cran d'armement, tourner la tête et déclencher la mise à feu","Refroidir et jeter la fusée, recommencer si nécessaire"]},{"sid":"c:s-mir-01","mod":5684,"title":"Quelle est la portée du grand modèle de miroir de signalisation (modèle au CCA) par plein soleil ?","source":"cours","explanation":"<p>Grand modèle : 15 km (modèle au CCA) ; petit modèle : 5 km.</p>","cref":[{"page":25,"printed":"18","quote":"Grand modèle 15 KM (modèle au CCA)"}],"type":"mcq","input":"radio","options":[{"text":"5 km","correct":false},{"text":"15 km","correct":true},{"text":"32 km","correct":false},{"text":"1 km","correct":false}]},{"sid":"c:s-mir-02","mod":5684,"title":"Le miroir ne doit être utilisé que lorsque les secours sont vus ou entendus.","source":"cours","explanation":"<p>Faux. On l'utilise tout au long de la survie quand il y a du soleil, même si les secours ne sont ni vus ni entendus. Tous les survivants peuvent l'utiliser.</p>","cref":[{"page":25,"printed":"18","quote":"même si les secours ne sont ni vus, ni entendus"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:s-mir-03","mod":5684,"title":"Remets dans l'ordre l'utilisation du miroir de signalisation.","source":"cours","explanation":"<p>Cordelette autour du cou, visée du soleil par l'œilleton, repérage du point rouge dans la main, on dirige vers la cible, puis on retire la main et on oscille légèrement.</p>","cref":[{"page":25,"printed":"18","quote":"Diriger sa main en gardant le point rouge vers la cible visée"}],"type":"order","items":["Passer la cordelette autour du cou","L'œil contre la face noire, viser le soleil à travers l'œilleton","Positionner l'autre main devant le miroir pour repérer le point rouge dans le creux de la main","Diriger sa main en gardant le point rouge vers la cible visée","Enlever sa main et osciller légèrement sur la cible"]},{"sid":"c:s-app-01","mod":5686,"title":"Qu'appelle-t-on le « kit de survie » ?","source":"cours","explanation":"<p>Lot de survie : terrestre, selon la zone survolée. Container : solidaire du toboggan convertible ou du canot. Kit de survie : les apparaux en commun au lot ET au container (miroir, moyens pyrotechniques, fluorescéine).</p>","cref":[{"page":26,"printed":"19","quote":"Kit de survie : terme utilisé pour désigner les apparaux en commun contenus dans le lot ET le container"}],"type":"mcq","input":"radio","options":[{"text":"Les apparaux en commun contenus dans le lot ET le container","correct":true},{"text":"Le lot de survie terrestre selon la zone survolée","correct":false},{"text":"Le container solidaire du toboggan convertible","correct":false},{"text":"La trousse de premiers secours","correct":false}]},{"sid":"c:s-app-02","mod":5686,"title":"Où sont imprimés les codes OACI des bandes sol-air ?","source":"cours","explanation":"<p>3 ou 4 bandes de tissu bicolore (rouge et blanc) de 3 m × 0,50 m, codes OACI imprimés sur la face blanche.</p>","cref":[{"page":26,"printed":"19","quote":"Pour réaliser des Codes OACI imprimés sur la face blanche"}],"type":"mcq","input":"radio","options":[{"text":"Sur la face blanche des bandes","correct":true},{"text":"Sur la face rouge","correct":false},{"text":"Dans le manuel de bord uniquement","correct":false},{"text":"Sur la balise","correct":false}]},{"sid":"c:s-app-03","mod":5686,"title":"Remets dans l'ordre l'utilisation des bandes sol-air.","source":"cours","explanation":"<p>Endroit dégagé et couleur adaptée au sol, puis disposition selon le code OACI, immobilisation et surveillance pendant toute la survie.</p>","cref":[{"page":26,"printed":"19","quote":"Immobiliser les bandes par tout moyen disponible"}],"type":"order","items":["Dans un endroit dégagé, choisir la couleur la plus visible avec la nature du sol","Disposer toutes les bandes conformément au message à transmettre (code OACI)","Immobiliser les bandes par tout moyen disponible","Surveiller tout au long de la survie"]},{"sid":"c:s-app-04","mod":5686,"title":"Associe chaque modèle de fluorescéine à sa durée d'action.","source":"cours","explanation":"<p>Bloc/pain : 6 à 8 h, par érosion. Sachet : 2 à 3 h, en poudre libre.</p>","cref":[{"page":27,"printed":"20","quote":"Bloc/pain : 6 à 8 heures (principe d’érosion)"}],"type":"match","pairs":[{"left":"Bloc / pain","right":"6 à 8 heures (érosion)"},{"left":"Sachet","right":"2 à 3 heures (poudre libre)"}]},{"sid":"c:s-app-05","mod":5686,"title":"Fluorescéine en milieu POLAIRE : comment l'utiliser ?","source":"cours","explanation":"<p>Polaire : répandre ou frotter sur la plus grande surface de neige ou de glace. Tropical : attacher à un point fixe et mettre à l'eau. Maritime : attacher à la saisine côté ancre flottante.</p>","cref":[{"page":27,"printed":"20","quote":"Répandre ou frotter sur la plus grande surface possible de neige ou de glace"}],"type":"mcq","input":"radio","options":[{"text":"Répandre ou frotter sur la plus grande surface possible de neige ou de glace","correct":true},{"text":"L'attacher à un point fixe et la mettre à l'eau","correct":false},{"text":"L'attacher à la saisine côté ancre flottante","correct":false},{"text":"Elle ne s'utilise pas en polaire","correct":false}]},{"sid":"c:s-app-06","mod":5686,"title":"Quelle précaution prendre avant d'utiliser le matériel du canot (apparaux) ?","source":"cours","explanation":"<p>Précaution : attacher le matériel à la saisine de l'embarcation avant utilisation.</p>","cref":[{"page":28,"printed":"21","quote":"Attacher le matériel à la saisine de l’embarcation avant utilisation"}],"type":"mcq","input":"radio","options":[{"text":"L'attacher à la saisine de l'embarcation","correct":true},{"text":"Le sécher","correct":false},{"text":"Demander l'accord de l'équipage de conduite","correct":false},{"text":"Le tester avant la survie","correct":false}]},{"sid":"c:s-cag-01","mod":5687,"title":"Remets dans l'ordre la prévol de la cagoule de protection respiratoire.","source":"cours","explanation":"<p>Prévol cagoule : présence, état et mobilité, poids d'environ 2,4 kg, scellé, témoin vert (rouge = faire remplacer), plaquette de validité de 10 ans, arrimage, puis « prévol terminée ».</p>","cref":[{"page":29,"printed":"22","quote":"Poids d’environ 2,4 kilos attestant la présence de la cagoule"}],"type":"order","items":["Présence de la boîte conforme au plan d'armement","Bon état général et bonne mobilité en la sortant du logement","Poids d'environ 2,4 kilos attestant la présence de la cagoule","Présence du scellé","Témoin de validité vert","Plaquette de validité (10 ans)","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-cag-02","mod":5687,"title":"Remets dans l'ordre la mise en place de la cagoule.","source":"cours","explanation":"<p>Pouces aux repères, coup sec pour la déployer, puis on l'enfile de l'arrière vers l'avant comme une casquette. On termine par l'étanchéité de la collerette et la membrane phonique devant la bouche.</p>","cref":[{"page":30,"printed":"23","quote":"Enfiler la cagoule de l'arrière vers l'avant (comme une casquette)"}],"type":"order","items":["Sortir la boîte de son emplacement, sortir le sachet contenant la cagoule et l'ouvrir","Sortir la cagoule","À deux mains, écarter la collerette avec les pouces au niveau des repères","Donner un coup sec de haut en bas pour la déployer","Enfiler la cagoule de l'arrière vers l'avant (comme une casquette)","Vérifier l'étanchéité de la collerette et positionner la membrane phonique devant la bouche"]},{"sid":"c:s-cag-03","mod":5687,"title":"En combien de temps la cagoule peut-elle être sortie de sa boîte et mise en place ?","source":"cours","explanation":"<p>La cagoule peut être retirée de sa boîte et mise en place en moins de 8 secondes. Elle dure environ 15 min jusqu'à 25 000 pieds d'altitude cabine.</p>","cref":[{"page":29,"printed":"22","quote":"La cagoule peut être retirée de sa boîte et mise en place en moins de 8 secondes"}],"type":"mcq","input":"radio","options":[{"text":"Moins de 8 secondes","correct":true},{"text":"Moins de 30 secondes","correct":false},{"text":"Environ 1 minute","correct":false},{"text":"Moins de 15 secondes","correct":false}]},{"sid":"c:s-cag-04","mod":5687,"title":"Le témoin de validité de la cagoule est rouge lors de la prévol. Que faites-vous ?","source":"cours","explanation":"<p>Le témoin de validité doit être vert ; s'il est rouge, il faut faire remplacer la cagoule.</p>","cref":[{"page":29,"printed":"22","quote":"Témoin de validité vert (si rouge faire remplacer la cagoule)"}],"type":"mcq","input":"radio","options":[{"text":"Faire remplacer la cagoule","correct":true},{"text":"Rien, c'est normal","correct":false},{"text":"Vérifier le poids et continuer","correct":false},{"text":"Retirer le scellé pour vérifier","correct":false}]},{"sid":"c:s-cag-05","mod":5687,"title":"Qu'est-ce qui absorbe le CO2 à l'intérieur de la cagoule ?","source":"cours","explanation":"<p>Intérieur : un tore stockant l'oxygène (libéré au passage de la tête grâce à la palette de déclenchement) et 2 cartouches filtrantes de chaux sodée qui absorbent le CO2.</p>","cref":[{"page":29,"printed":"22","quote":"2 cartouches filtrantes absorbant le CO2 (chaux sodée)"}],"type":"mcq","input":"radio","options":[{"text":"2 cartouches filtrantes (chaux sodée)","correct":true},{"text":"La soupape de surpression","correct":false},{"text":"Le tore stockant l'oxygène","correct":false},{"text":"La collerette d'étanchéité","correct":false}]},{"sid":"c:s-o2-01","mod":5687,"title":"Remets dans l'ordre la prévol de la bouteille d'oxygène.","source":"cours","explanation":"<p>Prévol O2 : présence, état, sangle, bouteille pleine (manomètre), obturateur sur la prise baïonnette, sélecteur non grippé, arrimage, puis « prévol terminée ».</p>","cref":[{"page":31,"printed":"24","quote":"Présence de l’obturateur sur la prise baïonnette"}],"type":"order","items":["Présence conforme au plan d'armement","Bon état général","Bonne fixation de la sangle en bon état","Bouteille pleine (aiguille du manomètre)","Présence de l'obturateur sur la prise baïonnette","Sélecteur non grippé","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-o2-02","mod":5687,"title":"Associe chaque débit d'oxygène à son autonomie et à son public.","source":"cours","explanation":"<p>Bouteille de 310 L : 4 L/min pendant 1h15 pour les enfants et les adultes, 2 L/min pendant 2h30 pour les bébés. Débit continu.</p>","cref":[{"page":31,"printed":"24","quote":"4L/min pendant 1h15 pour les enfants et les adultes"},{"page":31,"printed":"24","quote":"2L/min pendant 2h30 pour les bébés"}],"type":"match","pairs":[{"left":"4 L/min","right":"1h15, enfants et adultes"},{"left":"2 L/min","right":"2h30, bébés"}]},{"sid":"c:s-o2-03","mod":5687,"title":"Quelles sont les précautions avant d'administrer de l'oxygène ?","source":"cours","explanation":"<p>Précautions O2 : prévenir l'équipage de conduite, interdire de fumer et vérifier l'application de la consigne, enlever les corps gras du visage.</p>","cref":[{"page":31,"printed":"24","quote":"Interdire de fumer et vérifier l’application de la consigne"}],"type":"mcq","input":"checkbox","options":[{"text":"Prévenir l'équipage de conduite","correct":true},{"text":"Interdire de fumer et vérifier l'application de la consigne","correct":true},{"text":"Enlever les corps gras du visage","correct":true},{"text":"Mettre une cagoule de protection respiratoire","correct":false}]},{"sid":"c:s-o2-04","mod":5687,"title":"Quelle est la capacité de la bouteille d'oxygène Avox ?","source":"cours","explanation":"<p>Capacité : 310 L d'oxygène sous pression, délivré en débit continu.</p>","cref":[{"page":31,"printed":"24","quote":"Capacité de 310L d’oxygène sous pression"}],"type":"mcq","input":"radio","options":[{"text":"120 L","correct":false},{"text":"310 L","correct":true},{"text":"500 L","correct":false},{"text":"1000 L","correct":false}]},{"sid":"c:s-ext-01","mod":5688,"title":"Remets dans l'ordre la prévol de l'extincteur H2O.","source":"cours","explanation":"<p>Prévol H2O : présence, état, fil plombé, cartouche de CO2 dans la poignée, gicleur non obstrué, plaquette de validité, arrimage, puis « prévol terminée ».</p>","cref":[{"page":34,"printed":"27","quote":"Cartouche de CO2 dans la poignée"}],"type":"order","items":["Présence conforme au plan d'armement","Bon état général","Fil plombé","Cartouche de CO2 dans la poignée","Gicleur non obstrué","Plaquette de validité","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-ext-02","mod":5688,"title":"Remets dans l'ordre la prévol de l'extincteur P3 Hafex.","source":"cours","explanation":"<p>Prévol P3 Hafex : présence, état, manomètre dans la plage verte, diffuseur non obstrué, goupille plombée, plaquette de validité, arrimage, puis « prévol terminée ».</p>","cref":[{"page":35,"printed":"28","quote":"Aiguille du manomètre dans la plage verte"}],"type":"order","items":["Présence conforme au plan d'armement","Bon état général","Aiguille du manomètre dans la plage verte","Diffuseur non obstrué","Goupille plombée","Plaquette de validité","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-ext-03","mod":5688,"title":"Associe chaque extincteur à son type de feu.","source":"cours","explanation":"<p>H2O : feux secs (classe A). P3 Hafex : tout type de feux (A, B, C). Extincteur fixe : poubelles de toilette.</p>","cref":[{"page":34,"printed":"27","quote":"Agit sur les feux secs (classe A)"},{"page":35,"printed":"28","quote":"Agit sur tout type de feux (A, B, C)"},{"page":36,"printed":"29","quote":"Agit sur les feux de poubelles de toilette"}],"type":"match","pairs":[{"left":"H2O","right":"Feux secs (classe A)"},{"left":"P3 Hafex","right":"Tout type de feux (A, B, C)"},{"left":"Extincteur fixe","right":"Feux de poubelles de toilette"}]},{"sid":"c:s-ext-04","mod":5688,"title":"Associe chaque extincteur à sa durée d'action.","source":"cours","explanation":"<p>H2O : 30 s. P3 Hafex : 9 à 10 s. Extincteur fixe : 3 à 5 s.</p>","cref":[{"page":34,"printed":"27","quote":"Pendant 30 secondes"},{"page":35,"printed":"28","quote":"Pendant 9 à 10 secondes par refroidissement et étouffement"},{"page":36,"printed":"29","quote":"Pendant 3 à 5 secondes par inhibition"}],"type":"match","pairs":[{"left":"H2O","right":"30 secondes"},{"left":"P3 Hafex","right":"9 à 10 secondes"},{"left":"Extincteur fixe","right":"3 à 5 secondes"}]},{"sid":"c:s-ext-05","mod":5688,"title":"Associe chaque extincteur à son mode d'action.","source":"cours","explanation":"<p>H2O : refroidissement, étouffement et dispersion. P3 Hafex : refroidissement et étouffement. Fixe : inhibition.</p>","cref":[{"page":34,"printed":"27","quote":"par refroidissement, étouffement et dispersion"},{"page":35,"printed":"28","quote":"par refroidissement et étouffement"},{"page":36,"printed":"29","quote":"par inhibition"}],"type":"match","pairs":[{"left":"H2O","right":"Refroidissement, étouffement et dispersion"},{"left":"P3 Hafex","right":"Refroidissement et étouffement"},{"left":"Extincteur fixe","right":"Inhibition"}]},{"sid":"c:s-ext-06","mod":5688,"title":"Associe chaque extincteur à sa précaution.","source":"cours","explanation":"<p>H2O : accord de l'équipage de conduite. P3 Hafex : cagoule de protection respiratoire. Fixe : logement poubelle confiné et étanche.</p>","cref":[{"page":34,"printed":"27","quote":"PRECAUTION Demander l'accord à l'équipage de conduite"},{"page":35,"printed":"28","quote":"PRECAUTION Cagoule de protection respiratoire"},{"page":36,"printed":"29","quote":"PRECAUTION Dans un logement poubelle confiné et étanche"}],"type":"match","pairs":[{"left":"H2O","right":"Demander l'accord à l'équipage de conduite"},{"left":"P3 Hafex","right":"Cagoule de protection respiratoire"},{"left":"Extincteur fixe","right":"Logement poubelle confiné et étanche"}]},{"sid":"c:s-ext-07","mod":5688,"title":"Que contient l'extincteur P3 Hafex ?","source":"cours","explanation":"<p>P3 Hafex : 1,6 kg d'halotron BRX (2BTP). H2O : 2 L d'eau et de glycol (antigel). Fixe : 100 g d'hydrocarbure halogéné.</p>","cref":[{"page":35,"printed":"28","quote":"1,6 kilos d’halotron BRX (2BTP)"}],"type":"mcq","input":"radio","options":[{"text":"1,6 kg d'halotron BRX (2BTP)","correct":true},{"text":"2 L d'eau et de glycol","correct":false},{"text":"100 g d'hydrocarbure halogéné","correct":false},{"text":"2 kg de poudre","correct":false}]},{"sid":"c:s-ext-08","mod":5688,"title":"À quelle température fond l'embout des buses de l'extincteur fixe ?","source":"cours","explanation":"<p>L'embout des buses fond à environ 80 °C, ce qui déclenche l'extincteur fixe.</p>","cref":[{"page":36,"printed":"29","quote":"L’embout des buses fond à une température d’environ 80°C"}],"type":"mcq","input":"radio","options":[{"text":"Environ 50 °C","correct":false},{"text":"Environ 80 °C","correct":true},{"text":"Environ 120 °C","correct":false},{"text":"Environ 200 °C","correct":false}]},{"sid":"c:s-ext-09","mod":5688,"title":"Prévol de l'extincteur fixe : les pastilles témoins sont grises. Qu'est-ce que cela signifie ?","source":"cours","explanation":"<p>Les pastilles témoins d'élévation de température grisent au contact de la chaleur ; si elles sont grises, il faut appeler la maintenance.</p>","cref":[{"page":36,"printed":"29","quote":"(si grises = maintenance)"}],"type":"mcq","input":"radio","options":[{"text":"Il y a eu une élévation de température : maintenance","correct":true},{"text":"L'extincteur est plein","correct":false},{"text":"C'est leur couleur normale","correct":false},{"text":"La trappe n'est pas étanche","correct":false}]},{"sid":"c:s-ext-10","mod":5688,"title":"À quelle distance du foyer utiliser l'extincteur H2O ?","source":"cours","explanation":"<p>H2O : à 1 m. P3 Hafex : à 1,5 à 2 m.</p>","cref":[{"page":34,"printed":"27","quote":"À une distance d'1 mètre"},{"page":35,"printed":"28","quote":"À une distance d'1,5 à 2 mètres"}],"type":"mcq","input":"radio","options":[{"text":"1 mètre","correct":true},{"text":"1,5 à 2 mètres","correct":false},{"text":"3 mètres","correct":false},{"text":"50 centimètres","correct":false}]},{"sid":"c:s-ext-11","mod":5688,"title":"L'extincteur H2O sert aussi à refroidir les foyers déjà éteints.","source":"cours","explanation":"<p>Vrai. L'extincteur H2O sert aussi à refroidir les foyers déjà éteints.</p>","cref":[{"page":34,"printed":"27","quote":"Sert aussi à refroidir les foyers déjà éteints"}],"type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}]},{"sid":"c:s-hac-01","mod":5689,"title":"Remets dans l'ordre l'utilisation de la hache.","source":"cours","explanation":"<p>Accord de l'équipage, extincteur + cagoule + hache, passagers déplacés en tenant compte du centrage, housse retirée, attention aux câbles. Puis on arrache le revêtement, on rend compte et on surveille.</p>","cref":[{"page":38,"printed":"31","quote":"Faire déplacer les passagers à proximité en tenant compte du centrage"}],"type":"order","items":["Demander l'accord à l'équipage de conduite","Se munir d'un extincteur, d'une cagoule de protection respiratoire et de la hache","Faire déplacer les passagers à proximité en tenant compte du centrage","Retirer la housse en cuir","Prendre garde aux câbles, fils électriques et tuyauterie","Arracher le revêtement avec précaution","Rendre compte à l'équipage de conduite","Surveiller tout au long du vol"]},{"sid":"c:s-hac-02","mod":5689,"title":"Jusqu'à quelle tension le manche de la hache est-il isolant ?","source":"cours","explanation":"<p>Le manche de la hache est isolant jusqu'à 2000 volts.</p>","cref":[{"page":38,"printed":"31","quote":"Manche isolant jusqu’à 2000 volts"}],"type":"mcq","input":"radio","options":[{"text":"220 volts","correct":false},{"text":"1000 volts","correct":false},{"text":"2000 volts","correct":true},{"text":"5000 volts","correct":false}]},{"sid":"c:s-hac-03","mod":5689,"title":"Quelle est la longueur approximative du pied de biche ?","source":"cours","explanation":"<p>Barre métallique d'environ 40 cm : un côté plat pour fendre les cloisons, un côté courbé pour faire levier.</p>","cref":[{"page":37,"printed":"30","quote":"Barre métallique de 40 cm environ"}],"type":"mcq","input":"radio","options":[{"text":"20 cm","correct":false},{"text":"40 cm","correct":true},{"text":"60 cm","correct":false},{"text":"80 cm","correct":false}]},{"sid":"c:s-hac-04","mod":5689,"title":"À quoi servent la hache et le pied de biche ?","source":"cours","explanation":"<p>Ils permettent d'investiguer : vérifier que le feu ne s'est pas propagé derrière une cloison ou sous une moquette, et s'assurer de l'extinction totale d'un foyer.</p>","cref":[{"page":37,"printed":"30","quote":"Permettent d'investiguer/vérifier que le feu ne s'est pas propagé derrière une cloison"}],"type":"mcq","input":"radio","options":[{"text":"Investiguer : vérifier que le feu ne s'est pas propagé derrière une cloison ou sous une moquette, et s'assurer de l'extinction totale","correct":true},{"text":"Ouvrir une porte bloquée","correct":false},{"text":"Briser un hublot pour évacuer la fumée","correct":false},{"text":"Couper le filin d'amarrage","correct":false}]},{"sid":"c:s-hac-05","mod":5689,"title":"Remets dans l'ordre la prévol de la hache.","source":"cours","explanation":"<p>Prévol hache : présence, bon état (surtout le manche), housse en cuir plombée, arrimage, puis « prévol terminée ».</p>","cref":[{"page":38,"printed":"31","quote":"Bon état général et particulièrement du manche"}],"type":"order","items":["Présence conforme au plan d'armement","Bon état général et particulièrement du manche","Housse en cuir plombée","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-meg-01","mod":5690,"title":"Remets dans l'ordre la prévol du mégaphone.","source":"cours","explanation":"<p>Prévol mégaphone : présence, état (pavillon, micro, poignée, bouton), sangle, test en disant « test », arrimage, puis « prévol terminée ».</p>","cref":[{"page":39,"printed":"32","quote":"Test de fonctionnement dire : « test »"}],"type":"order","items":["Présence conforme au plan d'armement","Bon état général (pavillon, micro, poignée, bouton)","Présence de la sangle en bon état","Test de fonctionnement : dire « test »","Contrôle du système d'arrimage sur son support"]},{"sid":"c:s-meg-02","mod":5690,"title":"Quelle est la précaution d'utilisation du mégaphone ?","source":"cours","explanation":"<p>Précaution : sécuriser le mégaphone en passant la sangle en bandoulière.</p>","cref":[{"page":39,"printed":"32","quote":"Sécuriser en passant la sangle en bandoulière"}],"type":"mcq","input":"radio","options":[{"text":"Le sécuriser en passant la sangle en bandoulière","correct":true},{"text":"Demander l'accord de l'équipage de conduite","correct":false},{"text":"Parler le plus fort possible","correct":false},{"text":"Le tenir à 45° au-dessus de la tête","correct":false}]},{"sid":"c:s-meg-03","mod":5690,"title":"Quand utilise-t-on le mégaphone ?","source":"cours","explanation":"<p>Il sert à communiquer en cas de panne du PA ou à donner des ordres audibles lors d'une évacuation, à l'intérieur comme à l'extérieur. Il est alimenté par des piles.</p>","cref":[{"page":39,"printed":"32","quote":"Sert à communiquer en cas de panne du PA ou donner des ordres audibles"}],"type":"mcq","input":"radio","options":[{"text":"En cas de panne du PA, ou pour donner des ordres audibles lors d'une évacuation, à l'intérieur comme à l'extérieur","correct":true},{"text":"Uniquement à l'extérieur de l'avion","correct":false},{"text":"Uniquement pour les annonces commerciales","correct":false},{"text":"Uniquement en survie maritime","correct":false}]},{"sid":"c:s-fum-01","mod":5691,"title":"Remets dans l'ordre la conduite à tenir lors d'une détection de fumée dans une toilette.","source":"cours","explanation":"<p>Équipage prévenu, HORN OFF, toilette identifiée, extincteur + cagoule, intervention rapide. On rend compte et on demande l'autorisation de réarmer, RESET seulement après évacuation totale de la fumée, puis surveillance.</p>","cref":[{"page":41,"printed":"34","quote":"Arrêter l’alarme sonore en appuyant sur HORN OFF"},{"page":41,"printed":"34","quote":"Appuyer sur RESET après évacuation totale de la fumée"}],"type":"order","items":["Prévenir ou faire prévenir l'équipage de conduite","Arrêter l'alarme sonore en appuyant sur HORN OFF","Identifier la toilette concernée","Se munir d'un extincteur et d'une cagoule de protection respiratoire","Intervenir rapidement","Rendre compte à l'équipage de conduite et demander l'autorisation de réarmer le système","Appuyer sur RESET après évacuation totale de la fumée","Surveiller la zone"]},{"sid":"c:s-fum-02","mod":5691,"title":"Remets dans l'ordre la prévol du panneau de contrôle de détection de fumée.","source":"cours","explanation":"<p>TEST, puis HORN OFF, puis RESET, avec l'équipage de conduite, qui a des alarmes au cockpit et doit savoir que c'est un essai.</p>","cref":[{"page":40,"printed":"33","quote":"Appuyer sur TEST : déclenchement des alarmes visuelles et sonores ; les vérifier"}],"type":"order","items":["Appuyer sur TEST : déclenchement des alarmes visuelles et sonores, les vérifier","Appuyer sur HORN OFF : l'alarme sonore se coupe","Appuyer sur RESET"]},{"sid":"c:s-fum-03","mod":5691,"title":"Combien y a-t-il d'alarmes visuelles et sonores lors d'une détection de fumée ?","source":"cours","explanation":"<p>Visuelles (×4) : cockpit, cabine (barrettes), panneau de contrôle (LED rouge), répétiteur au-dessus de la toilette. Sonores (×3) : cockpit, cabine (haut-parleurs du PA), panneau de contrôle (buzzer).</p>","cref":[{"page":40,"printed":"33","quote":"Visuelles : (x4)"},{"page":40,"printed":"33","quote":"Sonores : (x3)"}],"type":"mcq","input":"radio","options":[{"text":"4 visuelles et 3 sonores","correct":true},{"text":"3 visuelles et 4 sonores","correct":false},{"text":"2 visuelles et 2 sonores","correct":false},{"text":"4 visuelles et 4 sonores","correct":false}]},{"sid":"c:s-fum-04","mod":5691,"title":"Associe chaque bouton du panneau de contrôle à son action.","source":"cours","explanation":"<p>HORN OFF : coupe l'alarme sonore uniquement. RESET : réinitialise le système. TEST : déclenche les alarmes pour la prévol collective ou la maintenance.</p>","cref":[{"page":40,"printed":"33","quote":"HORN OFF : arrête l’alarme sonore uniquement"}],"type":"match","pairs":[{"left":"HORN OFF","right":"Arrête l'alarme sonore uniquement"},{"left":"RESET","right":"Réinitialise le système"},{"left":"TEST","right":"Déclenche les alarmes (prévol ou maintenance)"}]},{"sid":"c:s-fum-05","mod":5691,"title":"Pourquoi la prévol du système de détection de fumée se fait-elle avec l'équipage de conduite ?","source":"cours","explanation":"<p>Ils ont des alarmes au cockpit et doivent nécessairement savoir que c'est un essai et non une alerte réelle.</p>","cref":[{"page":40,"printed":"33","quote":"doivent nécessairement être au courant que c’est un essai et non pas une alerte"}],"type":"mcq","input":"radio","options":[{"text":"Ils ont des alarmes au cockpit et doivent savoir que c'est un essai et non une alerte réelle","correct":true},{"text":"Seul le commandant peut appuyer sur TEST","correct":false},{"text":"Le panneau est dans le cockpit","correct":false},{"text":"Ce n'est pas obligatoire","correct":false}]},{"sid":"c:s-fum-06","mod":5691,"title":"Où trouve-t-on des systèmes de détection de fumée ?","source":"cours","explanation":"<p>Dans tous les endroits qui échappent à la vigilance de l'équipage : toilettes, soutes, postes repos.</p>","cref":[{"page":40,"printed":"33","quote":"les toilettes, les soutes, les postes repos"}],"type":"mcq","input":"radio","options":[{"text":"Dans les endroits qui échappent à la vigilance de l'équipage : toilettes, soutes, postes repos","correct":true},{"text":"Uniquement dans les toilettes","correct":false},{"text":"Uniquement dans le cockpit","correct":false},{"text":"Au-dessus de chaque rangée de sièges","correct":false}]}],"secourisme":[{"sid":"c:m-pec-01","mod":5021,"title":"Remets dans l'ordre les 4 temps de la prise en charge d'urgence d'un malade ou d'un blessé.","source":"cours","explanation":"<p>On observe et on interroge, puis on alerte (toujours un collègue et le responsable de cabine ; en cas de risque vital : CDB, médecin PAX, SAMU aéronautique). On secourt, puis on surveille.</p>","cref":[{"page":43,"printed":"36","quote":"OBERVER, INTERROGER"},{"page":43,"printed":"36","quote":"Systématiquement : un collègue, le Responsable de Cabine"}],"type":"order","items":["Observer, interroger","Alerter","Secourir","Surveiller"]},{"sid":"c:m-pec-02","mod":5021,"title":"En cas de risque vital, qui faut-il alerter ?","source":"cours","explanation":"<p>En cas de risque vital : le Commandant de Bord, un médecin PAX, le SAMU aéronautique. Systématiquement : un collègue et le responsable de cabine.</p>","cref":[{"page":43,"printed":"36","quote":"En cas de risque vital : le Commandant de Bord, un Médecin PAX, le SAMU aéronautique"}],"type":"mcq","input":"checkbox","options":[{"text":"Le Commandant de Bord","correct":true},{"text":"Un médecin PAX","correct":true},{"text":"Le SAMU aéronautique","correct":true},{"text":"Les pompiers de l'aéroport de départ","correct":false}]},{"sid":"c:m-pec-03","mod":5021,"title":"À quel intervalle surveille-t-on les fonctions vitales ?","source":"cours","explanation":"<p>Surveillance des fonctions vitales toutes les 5 minutes ; bilan post-immobilisation toutes les 15 minutes en cas de fracture.</p>","cref":[{"page":43,"printed":"36","quote":"Réaliser une surveillance des fonctions vitales toutes les 5 minutes"}],"type":"mcq","input":"radio","options":[{"text":"Toutes les 5 minutes","correct":true},{"text":"Toutes les 15 minutes","correct":false},{"text":"Toutes les 2 minutes","correct":false},{"text":"Toutes les 30 minutes","correct":false}]},{"sid":"c:m-pec-04","mod":5021,"title":"À quel intervalle fait-on un bilan post-immobilisation en cas de fracture ?","source":"cours","explanation":"<p>Bilan post-immobilisation toutes les 15 minutes dans le cas d'une fracture.</p>","cref":[{"page":43,"printed":"36","quote":"Réaliser un bilan post-immobilisation toutes les 15 minutes dans le cas d’une fracture"}],"type":"mcq","input":"radio","options":[{"text":"Toutes les 15 minutes","correct":true},{"text":"Toutes les 5 minutes","correct":false},{"text":"Toutes les heures","correct":false},{"text":"Une seule fois après l'immobilisation","correct":false}]},{"sid":"c:m-pec-05","mod":5021,"title":"Associe chaque âge à sa fréquence cardiaque normale.","source":"cours","explanation":"<p>Pouls : adulte 60-100 bpm, enfant (1-8 ans) 70-140 bpm, nourrisson (moins d'un an) 100-160 bpm.</p>","cref":[{"page":43,"printed":"36","quote":"Adulte : 60-100 bpm"},{"page":43,"printed":"36","quote":"Nourrisson (- 1an) : 100-160 bpm"}],"type":"match","pairs":[{"left":"Adulte","right":"60-100 bpm"},{"left":"Enfant (1-8 ans)","right":"70-140 bpm"},{"left":"Nourrisson (- 1 an)","right":"100-160 bpm"}]},{"sid":"c:m-pec-06","mod":5021,"title":"Associe chaque âge à sa fréquence respiratoire normale.","source":"cours","explanation":"<p>Respiration : adulte 15-20 mouvements/min, enfant (1-8 ans) 20-30, nourrisson 30-60.</p>","cref":[{"page":43,"printed":"36","quote":"Adulte : 15-20 mvts/min"},{"page":43,"printed":"36","quote":"Nourrisson (-1an) : 30-60 mvts/min"}],"type":"match","pairs":[{"left":"Adulte","right":"15-20 mvts/min"},{"left":"Enfant (1-8 ans)","right":"20-30 mvts/min"},{"left":"Nourrisson (- 1 an)","right":"30-60 mvts/min"}]},{"sid":"c:m-pou-01","mod":5021,"title":"Sur combien de temps prend-on le pouls ?","source":"cours","explanation":"<p>Le pouls se prend sur 1 minute complète ; on en évalue la fréquence, le rythme et l'amplitude.</p>","cref":[{"page":44,"printed":"37","quote":"Il se prend sur 1 minute complète"}],"type":"mcq","input":"radio","options":[{"text":"1 minute complète","correct":true},{"text":"15 secondes (× 4)","correct":false},{"text":"30 secondes (× 2)","correct":false},{"text":"10 secondes","correct":false}]},{"sid":"c:m-pou-02","mod":5021,"title":"Pourquoi ne faut-il pas prendre le pouls avec son pouce ?","source":"cours","explanation":"<p>On utilise 3 doigts (index, majeur, annulaire), jamais le pouce, sous peine de compter ses propres pulsations.</p>","cref":[{"page":44,"printed":"37","quote":"Ne pas prendre le pouls avec son pouce sous peine de compter ses propres pulsations"}],"type":"mcq","input":"radio","options":[{"text":"Sous peine de compter ses propres pulsations","correct":true},{"text":"Parce que le pouce appuie trop fort","correct":false},{"text":"Parce que c'est moins précis pour l'amplitude","correct":false},{"text":"Parce que cela fait mal au passager","correct":false}]},{"sid":"c:m-pou-03","mod":5021,"title":"Associe chaque pouls au passager sur lequel il se prend.","source":"cours","explanation":"<p>Radial : enfant ou adulte conscient. Carotidien : en principe, enfant ou adulte inconscient. Huméral : nourrisson.</p>","cref":[{"page":44,"printed":"37","quote":"Se prend sur un enfant ou un adulte conscient"},{"page":44,"printed":"37","quote":"Se prend chez le nourrisson"}],"type":"match","pairs":[{"left":"Pouls radial","right":"Enfant ou adulte conscient"},{"left":"Pouls carotidien","right":"En principe, enfant ou adulte inconscient"},{"left":"Pouls huméral","right":"Nourrisson"}]},{"sid":"c:m-pou-04","mod":5021,"title":"Pourquoi compter les pulsations sans regarder sa montre ?","source":"cours","explanation":"<p>On compte les pulsations sur 1 minute sans regarder sa montre, à cause du risque de compter les secondes.</p>","cref":[{"page":44,"printed":"37","quote":"en ne regardant pas sa montre : risque de compter"}],"type":"mcq","input":"radio","options":[{"text":"Pour ne pas risquer de compter les secondes","correct":true},{"text":"Pour rester concentré sur le passager","correct":false},{"text":"Parce que la trotteuse n'est pas nécessaire","correct":false},{"text":"Pour rassurer le passager","correct":false}]},{"sid":"c:m-pou-05","mod":5021,"title":"Où se prend le pouls huméral du nourrisson ?","source":"cours","explanation":"<p>Pouls huméral : extrémité de 2 doigts au niveau du bras, entre l'aisselle et le coude, plus près de l'aisselle.</p>","cref":[{"page":44,"printed":"37","quote":"niveau du bras, entre l’aisselle et le coude, plus près de l’aisselle"}],"type":"mcq","input":"radio","options":[{"text":"Au niveau du bras, entre l'aisselle et le coude, plus près de l'aisselle","correct":true},{"text":"Au poignet, dans la gouttière radiale","correct":false},{"text":"Sur le cou","correct":false},{"text":"Au pli de l'aine","correct":false}]},{"sid":"c:m-ta-01","mod":5021,"title":"Remets dans l'ordre la prise de tension artérielle (tensiomètre manuel, sans stéthoscope).","source":"cours","explanation":"<p>Brassard posé, aiguille à 0, valve fermée, pouls radial, gonflage jusqu'à environ 220 (le pouls disparaît). On dévisse doucement la valve et on annonce le chiffre divisé par 10 quand le pouls revient : c'est la tension maxima.</p>","cref":[{"page":45,"printed":"38","quote":"Gonfler le brassard jusqu’à ce que l’aiguille atteigne environ 220 sur le cadran"}],"type":"order","items":["Installer le brassard autour du bras, au-dessus du pli du coude, sur membre déshabillé","Vérifier que l'aiguille indique 0 et que le brassard est dégonflé","Fermer la valve du ballonnet","Prendre le pouls radial avec 3 doigts","Gonfler le brassard jusqu'à environ 220 : le pouls radial disparaît","Dévisser progressivement la valve","Annoncer le chiffre (divisé par 10) quand le pouls est de nouveau perçu"]},{"sid":"c:m-ta-02","mod":5021,"title":"Quelle est la norme de la tension maxima (systolique) ?","source":"cours","explanation":"<p>La norme de la tension maxima se situe entre 105 et 140 mmHg.</p>","cref":[{"page":45,"printed":"38","quote":"la norme de la tension maxima se situe"}],"type":"mcq","input":"radio","options":[{"text":"Entre 105 et 140 mmHg","correct":true},{"text":"Entre 60 et 90 mmHg","correct":false},{"text":"Entre 140 et 180 mmHg","correct":false},{"text":"Entre 90 et 100 mmHg","correct":false}]},{"sid":"c:m-ta-03","mod":5021,"title":"La méthode du tensiomètre sans stéthoscope permet de mesurer la tension minima.","source":"cours","explanation":"<p>Faux. Cette méthode ne permet pas de déterminer la tension minima, qui nécessite un stéthoscope.</p>","cref":[{"page":45,"printed":"38","quote":"Cette méthode ne permet pas de déterminer la tension artérielle minima"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:m-hyp-01","mod":5021,"title":"Quels signes présente un passager en hyperventilation ?","source":"cours","explanation":"<p>Respiration anormale, accélérée et superficielle, fourmillements dans les mains, éventuellement des crampes ; élimination trop importante de CO2.</p>","cref":[{"page":46,"printed":"39","quote":"Une respiration anormale, accélérée et superficielle"}],"type":"mcq","input":"checkbox","options":[{"text":"Respiration anormale, accélérée et superficielle","correct":true},{"text":"Fourmillements dans les mains","correct":true},{"text":"Éventuellement des crampes","correct":true},{"text":"Perte de connaissance immédiate","correct":false}]},{"sid":"c:m-hyp-02","mod":5021,"title":"Avec quoi fait-on respirer un passager en hyperventilation ?","source":"cours","explanation":"<p>On fait respirer dans un sac vomitoire ou dans un masque d'oxygène non branché à une bouteille.</p>","cref":[{"page":46,"printed":"39","quote":"Faire respirer dans un sac vomitoire ou dans un masque d’oxygène non branché"}],"type":"mcq","input":"radio","options":[{"text":"Un sac vomitoire ou un masque d'oxygène NON branché","correct":true},{"text":"Un masque d'oxygène branché à 4 L/min","correct":false},{"text":"L'insufflateur manuel","correct":false},{"text":"Rien, il faut le laisser respirer à l'air libre","correct":false}]},{"sid":"c:m-hyp-03","mod":5021,"title":"Hyperventilation : quelles actions le PNC doit-il mener ?","source":"cours","explanation":"<p>Rassurer et isoler, faire ralentir la respiration (suivre le rythme du PNC), faire respirer dans un sac vomitoire ou un masque non branché, et appeler un médecin si nécessaire.</p>","cref":[{"page":46,"printed":"39","quote":"Rassurer et isoler le PAX"}],"type":"mcq","input":"checkbox","options":[{"text":"Rassurer et isoler le PAX","correct":true},{"text":"Faire ralentir sa fréquence respiratoire en l'incitant à suivre le rythme du PNC","correct":true},{"text":"Appeler un médecin si nécessaire","correct":true},{"text":"L'allonger en PLS","correct":false}]},{"sid":"c:m-ext-01","mod":5021,"title":"Quelles sont les 3 réponses recherchées lors d'un bilan de conscience ?","source":"cours","explanation":"<p>Bilan de conscience : réponse verbale, réponse motrice à un ordre simple et ouverture des yeux sur demande.</p>","cref":[{"page":47,"printed":"40","quote":"Réaliser un bilan de conscience en recherchant 3 types de réponse"}],"type":"mcq","input":"checkbox","options":[{"text":"La réponse verbale à une question simple","correct":true},{"text":"La réponse motrice à un ordre simple (« Serrez-moi la main »)","correct":true},{"text":"L'ouverture des yeux sur demande","correct":true},{"text":"La réaction à la douleur (pincement)","correct":false}]},{"sid":"c:m-ext-02","mod":5021,"title":"Le PAX est inconscient. Après avoir fait alerter le CDB, que demande-t-on ?","source":"cours","explanation":"<p>Faire alerter le CDB et demander DSA, insufflateur et O2. Il vaut toujours mieux sortir le matériel de réanimation, même inutile, que le demander tardivement.</p>","cref":[{"page":47,"printed":"40","quote":"Demander DSA, Insufflateur, O2"}],"type":"mcq","input":"radio","options":[{"text":"DSA, insufflateur, O2","correct":true},{"text":"La trousse de premiers secours","correct":false},{"text":"Une couverture et un oreiller","correct":false},{"text":"Le tensiomètre","correct":false}]},{"sid":"c:m-ext-03","mod":5021,"title":"Remets dans l'ordre la préparation de l'extraction de siège.","source":"cours","explanation":"<p>Sièges voisins libérés, ceinture détachée, accoudoirs relevés, pieds groupés vers l'allée.</p>","cref":[{"page":47,"printed":"40","quote":"Libérer les 2 sièges voisins"}],"type":"order","items":["Libérer les 2 sièges voisins","Vérifier que la ceinture soit bien détachée","Relever les accoudoirs","Grouper les pieds du PAX latéralement, pieds tournés vers l'allée"]},{"sid":"c:m-ext-04","mod":5021,"title":"Méthode d'extraction « directe » : remets les étapes dans l'ordre.","source":"cours","explanation":"<p>Genou sur le siège voisin, main du PAX sur ses genoux, tête soutenue en empaumant le menton, buste basculé. Poignets croisés, joue contre la tempe, puis extraction directe vers l'allée en maintenant bien la tête pour éviter un traumatisme cervical.</p>","cref":[{"page":47,"printed":"40","quote":"Mettre son genou sur le siège voisin"},{"page":47,"printed":"40","quote":"Passer l’autre main sous l’aisselle et caler sa joue"}],"type":"order","items":["Mettre son genou sur le siège voisin","Mettre la main du PAX, côté allée, sur ses genoux","Passer sa main côté allée sous l'aisselle du PAX et soutenir la tête en empaumant le menton","Basculer le buste du PAX vers l'avant en maintenant le thorax","Passer son bras derrière le dos du PAX et croiser ses poignets sur ses genoux","Passer l'autre main sous l'aisselle et caler sa joue contre la tempe du PAX","Déplacer le PAX verticalement et directement vers l'allée, l'allonger sur le sol"]},{"sid":"c:m-ext-05","mod":5021,"title":"Quand utilise-t-on la méthode d'extraction « latérale » ?","source":"cours","explanation":"<p>Méthode latérale : si le PAX est trop lourd et que l'espace entre les rangées le permet. On le fait glisser de siège en siège, puis on reprend à l'étape 3 de la méthode directe.</p>","cref":[{"page":48,"printed":"41","quote":"Si le PAX est trop lourd et que l’espace entre les"}],"type":"mcq","input":"radio","options":[{"text":"Si le PAX est trop lourd et que l'espace entre les rangées le permet","correct":true},{"text":"Si le PAX est conscient","correct":false},{"text":"Toujours chez l'enfant","correct":false},{"text":"Si le PAX est assis côté allée","correct":false}]},{"sid":"c:m-mal-01","mod":5021,"title":"Malaise vagal : comment installer le PAX conscient ?","source":"cours","explanation":"<p>Installation : allongé sur le dos ou assis en cas de difficultés respiratoires (sinon dans la position où il se sent le mieux), couverture, col/cravate/ceinture dégrafés, O2 à 4 L/min.</p>","cref":[{"page":49,"printed":"42","quote":"Administrer de l’oxygène à 4L/min"}],"type":"mcq","input":"checkbox","options":[{"text":"Allongé sur le dos (ou assis en cas de difficultés respiratoires)","correct":true},{"text":"Proposer une couverture","correct":true},{"text":"Dégrafer col, cravate et ceinture","correct":true},{"text":"Administrer de l'oxygène à 4 L/min","correct":true},{"text":"Le placer en PLS","correct":false}]},{"sid":"c:m-mal-02","mod":5021,"title":"Malaise vagal : remets dans l'ordre le questionnement « MATHS ».","source":"cours","explanation":"<p>MATHS : Maladies (état de santé), Âge, Traitement médical, Hospitalisation récente, Sucre (dernier repas, boisson sucrée si besoin).</p>","cref":[{"page":49,"printed":"42","quote":"Questionner sur les signes du malaise : (MATHS)"}],"type":"order","items":["Maladies (état de santé)","Âge","Traitement médical en cours","Hospitalisation récente","Sucre (heure du dernier repas, boisson sucrée)"]},{"sid":"c:m-mal-03","mod":5021,"title":"Quels sont des signes d'accident vasculaire cérébral à rechercher ?","source":"cours","explanation":"<p>Signes d'AVC : faiblesse ou paralysie d'un membre, déformation de la face, perte de vision, mal de tête soudain et sévère, perte d'équilibre, difficultés à s'exprimer ou à comprendre.</p>","cref":[{"page":50,"printed":"43","quote":"Faiblesse ou paralysie d’un membre"}],"type":"mcq","input":"checkbox","options":[{"text":"Faiblesse ou paralysie d'un membre","correct":true},{"text":"Déformation de la face","correct":true},{"text":"Difficultés à s'exprimer ou à comprendre","correct":true},{"text":"Mal de tête soudain, sévère et inhabituel","correct":true},{"text":"Fourmillements dans les deux mains après un stress","correct":false}]},{"sid":"c:m-mal-04","mod":5021,"title":"Dans quels cas le PNC doit-il faire un appel médecin (surveillance d'un malaise) ?","source":"cours","explanation":"<p>Appel médecin : perte de connaissance, absence de signes de vie, FR &lt; 10 ou &gt; 24/min, TA systolique &lt; 90 ou &gt; 160 mmHg.</p>","cref":[{"page":50,"printed":"43","quote":"appel si FR<10 ou >24/min"},{"page":50,"printed":"43","quote":"appel si TA<90 ou >160mmHg"}],"type":"mcq","input":"checkbox","options":[{"text":"Perte de connaissance","correct":true},{"text":"Absence de signes de vie","correct":true},{"text":"Fréquence respiratoire < 10 ou > 24/min","correct":true},{"text":"Tension systolique < 90 ou > 160 mmHg","correct":true},{"text":"Pouls à 80 bpm","correct":false}]},{"sid":"c:m-pls-01","mod":5021,"title":"Sur quel passager effectue-t-on une PLS ?","source":"cours","explanation":"<p>La PLS se fait sur un passager inconscient qui respire spontanément et efficacement. S'il ne respire pas, c'est une RCP.</p>","cref":[{"page":50,"printed":"43","quote":"La PLS s’effectue sur un passager inconscient, qui respire spontanément et"}],"type":"mcq","input":"radio","options":[{"text":"Un passager inconscient qui respire spontanément et efficacement","correct":true},{"text":"Un passager conscient qui a fait un malaise","correct":false},{"text":"Un passager inconscient qui ne respire pas","correct":false},{"text":"Un passager en hyperventilation","correct":false}]},{"sid":"c:m-pls-02","mod":5021,"title":"Sur combien de temps apprécie-t-on la respiration ?","source":"cours","explanation":"<p>L'appréciation de la respiration se fait sur 10 secondes, menton élevé et tête en hyperextension.</p>","cref":[{"page":51,"printed":"44","quote":"L’appréciation de la respiration se fait sur 10 secondes"}],"type":"mcq","input":"radio","options":[{"text":"10 secondes","correct":true},{"text":"5 secondes","correct":false},{"text":"30 secondes","correct":false},{"text":"1 minute","correct":false}]},{"sid":"c:m-pls-03","mod":5021,"title":"Remets dans l'ordre les 3 phases de la PLS.","source":"cours","explanation":"<p>La PLS se fait en 3 phases : préparation, retournement et stabilisation.</p>","cref":[{"page":52,"printed":"45","quote":"La PLS se fait en 3 phases : phase de préparation, phase de retournement et phase de"}],"type":"order","items":["Phase de préparation","Phase de retournement","Phase de stabilisation"]},{"sid":"c:m-pls-04","mod":5021,"title":"PLS, phase de préparation : remets les gestes dans l'ordre.","source":"cours","explanation":"<p>Lunettes retirées, jambes rapprochées, PNC à genoux au niveau du thorax, bras proche à angle droit, main opposée contre l'oreille, puis jambe opposée relevée, pied au sol.</p>","cref":[{"page":52,"printed":"45","quote":"Retirer les lunettes du PAX s’il en porte"}],"type":"order","items":["Retirer les lunettes du PAX s'il en porte","Rapprocher délicatement ses membres inférieurs de l'axe du corps","Se placer à genoux au niveau du thorax du PAX","Placer le bras le plus proche à angle droit, coude plié, paume vers le haut","Placer le dos de la main opposée du PAX contre son oreille, paume contre paume","Avec l'autre main, attraper la jambe opposée derrière le genou et la relever, pied au sol"]},{"sid":"c:m-pls-05","mod":5021,"title":"De quel côté met-on en PLS une passagère enceinte ou un PAX de forte corpulence ?","source":"cours","explanation":"<p>Côté gauche, afin d'éviter une détresse circulatoire par compression de certains vaisseaux sanguins dans l'abdomen.</p>","cref":[{"page":53,"printed":"46","quote":"la PLS devra se faire du côté gauche"}],"type":"mcq","input":"radio","options":[{"text":"Côté gauche","correct":true},{"text":"Côté droit","correct":false},{"text":"Côté allée","correct":false},{"text":"Peu importe","correct":false}]},{"sid":"c:m-pls-06","mod":5021,"title":"Le danger de détresse respiratoire prime sur l'éventualité d'aggraver une lésion traumatique lors de la mise en PLS.","source":"cours","explanation":"<p>Vrai. Le danger de détresse respiratoire prime sur l'éventualité de l'aggravation d'une lésion traumatique lors de la mise en PLS.</p>","cref":[{"page":53,"printed":"46","quote":"Le danger de détresse respiratoire prime sur l’éventualité de l’aggravation d’une"}],"type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}]},{"sid":"c:m-pls-07","mod":5021,"title":"Une fois en PLS, comment réchauffer et oxygéner le PAX ?","source":"cours","explanation":"<p>Le PAX doit ensuite être réchauffé (couverture) et oxygéné (O2 à 4 L/min).</p>","cref":[{"page":53,"printed":"46","quote":"Le PAX doit ensuite être réchauffé (couverture) et oxygéné (O2 à 4L/min)"}],"type":"mcq","input":"radio","options":[{"text":"Couverture et O2 à 4 L/min","correct":true},{"text":"Couverture et O2 à 2 L/min","correct":false},{"text":"Boisson chaude et O2 à 4 L/min","correct":false},{"text":"Rien, il ne faut plus le toucher","correct":false}]},{"sid":"c:m-lva-01","mod":5021,"title":"Remets dans l'ordre la libération des voies aériennes (LVA).","source":"cours","explanation":"<p>On desserre col, cravate et ceinture, puis on bascule la tête en arrière en élevant le menton. On ouvre la bouche et on retire les corps étrangers visibles, y compris les prothèses décrochées, sans toucher à celles restées en place.</p>","cref":[{"page":51,"printed":"44","quote":"Ouvrir la bouche du PAX avec la main qui tient le menton"}],"type":"order","items":["Desserrer col, cravate, ceinture","Basculer la tête vers l'arrière et simultanément élever le menton","Ouvrir la bouche du PAX avec la main qui tient le menton","Retirer les corps étrangers visibles avec la main qui était sur le front"]},{"sid":"c:m-lva-02","mod":5021,"title":"Lors de la LVA, que fait-on des prothèses dentaires ?","source":"cours","explanation":"<p>On retire les corps étrangers visibles, y compris les prothèses dentaires décrochées, sans toucher à celles qui sont restées en place.</p>","cref":[{"page":51,"printed":"44","quote":"les prothèses dentaires décrochées, sans toucher à celles"}],"type":"mcq","input":"radio","options":[{"text":"On retire celles qui sont décrochées, sans toucher à celles restées en place","correct":true},{"text":"On les retire toutes","correct":false},{"text":"On n'y touche jamais","correct":false},{"text":"On les remet en place","correct":false}]},{"sid":"c:m-obs-01","mod":5021,"title":"Obstruction PARTIELLE chez l'adulte (il tousse, parle) : que faire ?","source":"cours","explanation":"<p>En aucun cas le PNC ne pratique les techniques de désobstruction : elles risqueraient de provoquer une obstruction complète. On le laisse dans sa position, on l'encourage à tousser, on demande un avis médical et on administre de l'oxygène.</p>","cref":[{"page":54,"printed":"47","quote":"Encourager le PAX à tousser pour tenter de rejeter le corps étranger"}],"type":"mcq","input":"radio","options":[{"text":"Le laisser dans la position où il se sent le mieux et l'encourager à tousser","correct":true},{"text":"Pratiquer immédiatement 5 claques dorsales","correct":false},{"text":"Pratiquer des compressions abdominales","correct":false},{"text":"Le mettre en PLS","correct":false}]},{"sid":"c:m-obs-02","mod":5021,"title":"Quels signes indiquent une obstruction TOTALE des voies aériennes chez l'adulte conscient ?","source":"cours","explanation":"<p>Obstruction totale : agité, mains au cou, bouche grande ouverte, visage écarlate puis cyanosé, ne peut ni parler, ni respirer, ni tousser.</p>","cref":[{"page":54,"printed":"47","quote":"Il ne peut parler, respirer, tousser"}],"type":"mcq","input":"checkbox","options":[{"text":"Il porte les mains à son cou","correct":true},{"text":"Sa bouche est grande ouverte","correct":true},{"text":"Visage écarlate puis rapidement cyanosé","correct":true},{"text":"Il ne peut ni parler, ni respirer, ni tousser","correct":true},{"text":"Il tousse fortement","correct":false}]},{"sid":"c:m-obs-03","mod":5021,"title":"Obstruction totale chez l'adulte : remets dans l'ordre la conduite à tenir.","source":"cours","explanation":"<p>1 à 5 claques dorsales, puis 1 à 5 compressions abdominales, en alternance tant que l'obstruction persiste. Si le PAX devient inconscient, RCP immédiate en commençant par les compressions thoraciques, sans bilans préalables.</p>","cref":[{"page":55,"printed":"48","quote":"Si claques inefficaces : compressions abdominales"},{"page":56,"printed":"49","quote":"Pratiquer immédiatement une RCP en débutant par les compressions thoraciques sans"}],"type":"order","items":["1 à 5 claques dorsales","Si claques inefficaces : 1 à 5 compressions abdominales","Si l'obstruction persiste : alterner claques dorsales et compressions abdominales","Si le PAX tombe inconscient : RCP en débutant par les compressions thoraciques"]},{"sid":"c:m-obs-04","mod":5021,"title":"Où place-t-on le poing pour les compressions abdominales ?","source":"cours","explanation":"<p>Poing fermé (dos de la main vers le ciel) juste au-dessus du nombril, l'autre main sur le poing. On tire fortement vers l'arrière et vers le haut (en « U »).</p>","cref":[{"page":55,"printed":"48","quote":"Placer le poing fermé (dos de la main vers le ciel)"}],"type":"mcq","input":"radio","options":[{"text":"Juste au-dessus du nombril, dos de la main vers le ciel","correct":true},{"text":"Sur le sternum","correct":false},{"text":"Sous le nombril","correct":false},{"text":"Entre les omoplates","correct":false}]},{"sid":"c:m-obs-05","mod":5021,"title":"Avec quelle partie de la main donne-t-on les claques dorsales ?","source":"cours","explanation":"<p>1 à 5 claques dorsales avec le talon de la main ouverte entre les omoplates, la victime penchée en avant.</p>","cref":[{"page":55,"printed":"48","quote":"avec le talon de la main ouverte entre les omoplates"}],"type":"mcq","input":"radio","options":[{"text":"Le talon de la main ouverte, entre les omoplates","correct":true},{"text":"Le poing fermé, entre les omoplates","correct":false},{"text":"Le plat de la main, sur les reins","correct":false},{"text":"Le bout des doigts, sur la nuque","correct":false}]},{"sid":"c:m-obs-06","mod":5021,"title":"Obstruction totale chez un enfant de 6 ans : comment se place le PNC ?","source":"cours","explanation":"<p>Enfant de 6 ans : le PNC se met à genoux derrière l'enfant, les actions sont les mêmes que chez l'adulte. Enfant de 2 ans : un genou à terre, l'enfant basculé sur la cuisse, tête vers le sol.</p>","cref":[{"page":56,"printed":"49","quote":"Se place à genoux derrière l’enfant pour être à sa hauteur"}],"type":"mcq","input":"radio","options":[{"text":"À genoux derrière l'enfant, mêmes actions que chez l'adulte","correct":true},{"text":"Il bascule l'enfant sur sa cuisse, tête vers le sol","correct":false},{"text":"Il couche l'enfant sur son avant-bras","correct":false},{"text":"Debout devant l'enfant","correct":false}]},{"sid":"c:m-obs-07","mod":5021,"title":"Obstruction totale chez le NOURRISSON conscient : remets dans l'ordre.","source":"cours","explanation":"<p>Nourrisson à califourchon sur l'avant-bras, tête basse, puis 1 à 5 claques dans le dos. On le retourne face vers le ciel, on vérifie la bouche, puis 1 à 5 compressions thoraciques avec la pulpe de 2 doigts. On recommence tant qu'il reste conscient.</p>","cref":[{"page":57,"printed":"50","quote":"Tourner le nourrisson pour que sa face soit tournée vers le ciel"},{"page":58,"printed":"51","quote":"Effectuer 1 à 5 compressions profondes et successives"}],"type":"order","items":["Coucher le nourrisson à califourchon sur l'avant-bras, tête plus basse que le thorax","Donner 1 à 5 claques dans le dos, entre les omoplates","Retourner le nourrisson, face vers le ciel, tête plus basse que le corps","Vérifier que le corps étranger n'est pas dans la bouche","Effectuer 1 à 5 compressions thoraciques avec 2 doigts"]},{"sid":"c:m-obs-08","mod":5021,"title":"Nourrisson devenu inconscient après une obstruction : quel rythme de RCP ?","source":"cours","explanation":"<p>Plan dur, RCP immédiate en débutant par les compressions thoraciques sans rechercher les signes de vie. L'arrêt est dû à une hypoxie, les insufflations starters sont donc inutiles. Séries de 15 MCE + 2 BABN.</p>","cref":[{"page":58,"printed":"51","quote":"RCP se réalisera avec des séries de 15 MCE + 2 BABN"},{"page":58,"printed":"51","quote":"les insufflations starters sont donc inutiles"}],"type":"mcq","input":"radio","options":[{"text":"15 MCE + 2 BABN, en débutant par les compressions, sans insufflations starters","correct":true},{"text":"5 insufflations starters puis 15/2","correct":false},{"text":"30 compressions / 2 insufflations","correct":false},{"text":"Compressions seules","correct":false}]},{"sid":"c:m-acr-01","mod":5022,"title":"Quand une victime est-elle considérée en arrêt cardio-respiratoire ?","source":"cours","explanation":"<p>Une victime est considérée en ACR lorsqu'elle est inconsciente et ne respire plus.</p>","cref":[{"page":59,"printed":"52","quote":"est inconsciente et qu'elle ne respire plus"}],"type":"mcq","input":"radio","options":[{"text":"Lorsqu'elle est inconsciente et qu'elle ne respire plus","correct":true},{"text":"Lorsque son pouls est inférieur à 60","correct":false},{"text":"Lorsqu'elle est inconsciente","correct":false},{"text":"Lorsqu'elle présente des gasps et un pouls","correct":false}]},{"sid":"c:m-acr-02","mod":5022,"title":"De combien chaque minute gagnée dans la pose du DSA augmente-t-elle les chances de survie ?","source":"cours","explanation":"<p>La mise en place du DSA doit être précoce : chaque minute gagnée augmente de 10 % les chances de survie.</p>","cref":[{"page":60,"printed":"53","quote":"chaque minute gagnée dans la pose du DSA augmente de 10% les"}],"type":"mcq","input":"radio","options":[{"text":"10 %","correct":true},{"text":"5 %","correct":false},{"text":"25 %","correct":false},{"text":"50 %","correct":false}]},{"sid":"c:m-acr-03","mod":5022,"title":"Qu'est-ce qui accompagne toujours le DSA ?","source":"cours","explanation":"<p>Le DSA est toujours accompagné d'électrodes pré-gélifiées autocollantes avec câble intégré, de compresses pour sécher la peau et d'un rasoir jetable.</p>","cref":[{"page":60,"printed":"53","quote":"Le DSA est toujours accompagné"}],"type":"mcq","input":"checkbox","options":[{"text":"Une paire d'électrodes pré-gélifiées autocollantes","correct":true},{"text":"Des compresses pour sécher la poitrine","correct":true},{"text":"Un rasoir jetable","correct":true},{"text":"Un stéthoscope","correct":false}]},{"sid":"c:m-acr-04","mod":5022,"title":"À quel débit d'oxygène raccorde-t-on l'insufflateur manuel ?","source":"cours","explanation":"<p>Les insufflations se font avec l'insufflateur raccordé à la bouteille d'oxygène (débit de 4 L/min), insufflations d'une seconde.</p>","cref":[{"page":60,"printed":"53","quote":"raccordé à la bouteille d’oxygène (débit de"}],"type":"mcq","input":"radio","options":[{"text":"4 L/min","correct":true},{"text":"2 L/min","correct":false},{"text":"8 L/min","correct":false},{"text":"15 L/min","correct":false}]},{"sid":"c:m-rcp-01","mod":5022,"title":"Le PAX présente des gasps. Comment les considérer ?","source":"cours","explanation":"<p>Les gasps (perçus dans 40 % des cas) sont des mouvements pré mortem. Leur présence doit être traitée comme une respiration inexistante.</p>","cref":[{"page":62,"printed":"55","quote":"La présence de Gasps doit être traitée comme une respiration inexistante"}],"type":"mcq","input":"radio","options":[{"text":"Comme une respiration inexistante","correct":true},{"text":"Comme une respiration normale : mettre en PLS","correct":false},{"text":"Comme un signe de reprise de conscience","correct":false},{"text":"Comme une obstruction partielle","correct":false}]},{"sid":"c:m-rcp-02","mod":5022,"title":"Comment calcule-t-on l'heure TU en hiver ?","source":"cours","explanation":"<p>Heure TU : hiver = heure de Paris - 1 h ; été = heure de Paris - 2 h.</p>","cref":[{"page":62,"printed":"55","quote":"Heure TU : Hiver = Heure de Paris - 1H"}],"type":"mcq","input":"radio","options":[{"text":"Heure de Paris - 1 h","correct":true},{"text":"Heure de Paris - 2 h","correct":false},{"text":"Heure de Paris + 1 h","correct":false},{"text":"Heure de Paris","correct":false}]},{"sid":"c:m-rcp-03","mod":5022,"title":"Dans quel délai le PAX en arrêt doit-il être pris en charge pour augmenter ses chances de survie ?","source":"cours","explanation":"<p>La prise en charge du PAX doit se faire dans les 3-4 minutes afin d'augmenter les chances de survie.</p>","cref":[{"page":62,"printed":"55","quote":"La prise en charge du PAX doit se faire dans les 3-4 minutes"}],"type":"mcq","input":"radio","options":[{"text":"3-4 minutes","correct":true},{"text":"10 minutes","correct":false},{"text":"1 minute","correct":false},{"text":"15 minutes","correct":false}]},{"sid":"c:m-rcp-04","mod":5022,"title":"Chez l'adulte, quelle est la profondeur des compressions thoraciques ?","source":"cours","explanation":"<p>Adulte : 5 à 6 cm. Enfant : environ 1/3 du thorax (à peu près 4 cm). Nourrisson : environ 1/3 du thorax (à peu près 3 cm).</p>","cref":[{"page":63,"printed":"56","quote":"Réaliser des compressions thoraciques d'une profondeur de 5 à 6 cm"}],"type":"mcq","input":"radio","options":[{"text":"5 à 6 cm","correct":true},{"text":"3 cm","correct":false},{"text":"4 cm","correct":false},{"text":"8 à 10 cm","correct":false}]},{"sid":"c:m-rcp-05","mod":5022,"title":"Quelle est la fréquence des compressions thoraciques ?","source":"cours","explanation":"<p>Fréquence comprise entre 100 et 120 compressions par minute, chez l'adulte, l'enfant comme le nourrisson.</p>","cref":[{"page":63,"printed":"56","quote":"Maintenir une fréquence comprise entre 100 et 120"}],"type":"mcq","input":"radio","options":[{"text":"Entre 100 et 120 par minute","correct":true},{"text":"Entre 60 et 80 par minute","correct":false},{"text":"Entre 80 et 100 par minute","correct":false},{"text":"Plus de 140 par minute","correct":false}]},{"sid":"c:m-rcp-06","mod":5022,"title":"Compressions chez l'adulte : à quoi faut-il veiller ?","source":"cours","explanation":"<p>Bras verticaux et tendus, coudes verrouillés, appui vertical, 100-120/min, compression = relâchement, sans décoller les mains.</p>","cref":[{"page":63,"printed":"56","quote":"Assurer un temps de compression égal à celui du"}],"type":"mcq","input":"checkbox","options":[{"text":"Bras parfaitement verticaux et tendus","correct":true},{"text":"Coudes verrouillés","correct":true},{"text":"Temps de compression égal au temps de relâchement, sans décoller les mains","correct":true},{"text":"Décoller les mains entre chaque compression","correct":false}]},{"sid":"c:m-dsa-01","mod":5022,"title":"Préparation du PAX avant de coller les électrodes : que faut-il faire ?","source":"cours","explanation":"<p>Sécher une poitrine mouillée (compresses, papier, linge), raser une poitrine velue (rasoir de la boîte), enlever un patch médicamenteux et essuyer la peau.</p>","cref":[{"page":63,"printed":"56","quote":"Si la poitrine du PAX est velue, raser la zone où les électrodes doivent être"}],"type":"mcq","input":"checkbox","options":[{"text":"Sécher la poitrine si elle est mouillée","correct":true},{"text":"Raser la zone si la poitrine est velue","correct":true},{"text":"Enlever un patch médicamenteux et essuyer la peau","correct":true},{"text":"Appliquer du gel sur la poitrine","correct":false}]},{"sid":"c:m-dsa-02","mod":5022,"title":"Le PAX porte un stimulateur cardiaque sous la clavicule droite. Où coller l'électrode ?","source":"cours","explanation":"<p>On colle l'électrode à un travers de main du stimulateur, environ 8 cm en dessous de la bosse perçue.</p>","cref":[{"page":64,"printed":"57","quote":"coller l'électrode à un travers de main du"}],"type":"mcq","input":"radio","options":[{"text":"À un travers de main du stimulateur (environ 8 cm en dessous)","correct":true},{"text":"Directement sur le stimulateur","correct":false},{"text":"Dans le dos","correct":false},{"text":"Le DSA ne doit pas être utilisé","correct":false}]},{"sid":"c:m-dsa-03","mod":5022,"title":"Dans quels cas l'analyse du DSA peut-elle être faussée ?","source":"cours","explanation":"<p>L'analyse peut être faussée en cas de turbulences, au décollage, à l'atterrissage, ou si une personne ou quelque chose touche le PAX.</p>","cref":[{"page":64,"printed":"57","quote":"Si une personne ou quelque chose touche le PAX"}],"type":"mcq","input":"checkbox","options":[{"text":"En cas de turbulences","correct":true},{"text":"Au décollage","correct":true},{"text":"À l'atterrissage","correct":true},{"text":"Si une personne ou quelque chose touche le PAX","correct":true},{"text":"Si le PAX porte des lunettes","correct":false}]},{"sid":"c:m-dsa-04","mod":5022,"title":"Choc indiqué par le DSA : remets les annonces dans l'ordre.","source":"cours","explanation":"<p>On dit « Écartez-vous ! », puis juste avant le choc « Attention, je vais choquer ! », et au moment du choc « Attention, je choque ! », après avoir vérifié que rien ni personne ne touche le PAX.</p>","cref":[{"page":64,"printed":"57","quote":"Juste avant de déclencher le choc : « Attention, je vais choquer ! »"}],"type":"order","items":["« Écartez-vous ! »","« Attention, je vais choquer ! »","« Attention, je choque ! »"]},{"sid":"c:m-dsa-05","mod":5022,"title":"Toutes les combien de temps le DSA lance-t-il une analyse ?","source":"cours","explanation":"<p>Analyse toutes les 2 minutes ; plusieurs chocs peuvent être conseillés.</p>","cref":[{"page":66,"printed":"59","quote":"Analyse toutes les 2 minutes"}],"type":"mcq","input":"radio","options":[{"text":"Toutes les 2 minutes","correct":true},{"text":"Toutes les 5 minutes","correct":false},{"text":"Toutes les 30 secondes","correct":false},{"text":"Uniquement quand on appuie sur ON","correct":false}]},{"sid":"c:m-dsa-06","mod":5022,"title":"Le DSA déconseille le choc. Que doit faire le PNC 1 ?","source":"cours","explanation":"<p>Sans choc conseillé, le cœur a soit repris une activité normale, soit n'a plus d'activité : le PNC 1 demande au PNC 2 un bilan respiratoire.</p>","cref":[{"page":66,"printed":"59","quote":"PNC 2 d'effectuer un bilan respiratoire"}],"type":"mcq","input":"radio","options":[{"text":"Demander au PNC 2 d'effectuer un bilan respiratoire","correct":true},{"text":"Éteindre le DSA","correct":false},{"text":"Arrêter la réanimation","correct":false},{"text":"Retirer les électrodes","correct":false}]},{"sid":"c:m-dsa-07","mod":5022,"title":"Avec la technique de la pince C-E, que forment les 3e, 4e et 5e doigts ?","source":"cours","explanation":"<p>Le pouce et l'index forment un C sur le masque ; les 3e, 4e et 5e doigts, en crochet sous le menton, forment un E.</p>","cref":[{"page":65,"printed":"58","quote":"en crochet sous le menton"}],"type":"mcq","input":"radio","options":[{"text":"Un E, en crochet sous le menton","correct":true},{"text":"Un C, sur le masque","correct":false},{"text":"Un appui sur le front","correct":false},{"text":"Une pression sur le ballon","correct":false}]},{"sid":"c:m-dsa-08","mod":5022,"title":"En combien de temps maximum réalise-t-on les 2 insufflations ?","source":"cours","explanation":"<p>Les 2 insufflations se pratiquent en moins de 5 secondes, chacune durant environ une seconde.</p>","cref":[{"page":65,"printed":"58","quote":"Puis le PNC 1 pratique les 2 insufflations en moins de 5 secondes"}],"type":"mcq","input":"radio","options":[{"text":"Moins de 5 secondes","correct":true},{"text":"Moins de 10 secondes","correct":false},{"text":"Moins de 2 secondes","correct":false},{"text":"Moins de 15 secondes","correct":false}]},{"sid":"c:m-dsa-09","mod":5022,"title":"Si le ventre ou la poitrine ne se soulève pas lors des insufflations à l'insufflateur, il faut privilégier le MCE.","source":"cours","explanation":"<p>Vrai. Si le ventre ou la poitrine ne se soulève pas lors des insufflations manuelles, privilégier le MCE.</p>","cref":[{"page":65,"printed":"58","quote":"privilégier le MCE"}],"type":"truefalse","options":[{"text":"Vrai","correct":true},{"text":"Faux","correct":false}]},{"sid":"c:m-evo-01","mod":5022,"title":"PAX toujours inconscient et ne respirant pas : jusqu'à quand poursuit-on la réanimation ?","source":"cours","explanation":"<p>On poursuit jusqu'à : reprise des fonctions vitales, nouvelle analyse ou choc du DSA, relais par les secours ou un autre PNC ou secouriste, ordre d'un médecin présentant sa carte professionnelle, ou d'un médecin du SAMU par radio.</p>","cref":[{"page":66,"printed":"59","quote":"L'ordre d'arrêter donné par un médecin présentant sa carte professionnelle"}],"type":"mcq","input":"checkbox","options":[{"text":"Reprise des fonctions vitales","correct":true},{"text":"Relais par les secours ou par un autre PNC ou secouriste","correct":true},{"text":"Ordre d'arrêter d'un médecin présentant sa carte professionnelle","correct":true},{"text":"Ordre d'un médecin du SAMU contacté par radio","correct":true},{"text":"Décision du responsable de cabine","correct":false}]},{"sid":"c:m-evo-02","mod":5022,"title":"Le PAX est toujours inconscient mais respire : que faire ?","source":"cours","explanation":"<p>PLS, oxygène, couverture, DSA laissé en place et allumé (analyse toutes les 2 min), surveillance, heure TU de reprise de la respiration notée.</p>","cref":[{"page":66,"printed":"59","quote":"Si DSA, ne pas l’enlever ni l’éteindre car analyse toutes les 2 minutes"}],"type":"mcq","input":"checkbox","options":[{"text":"Le mettre en PLS","correct":true},{"text":"Lui délivrer de l'oxygène et le couvrir","correct":true},{"text":"Laisser le DSA en place et allumé","correct":true},{"text":"Noter l'heure TU de la reprise de la respiration","correct":true},{"text":"Éteindre le DSA","correct":false}]},{"sid":"c:m-evo-03","mod":5022,"title":"Le PAX a retrouvé sa conscience et respire : comment l'installer ?","source":"cours","explanation":"<p>On le laisse impérativement là où il se trouve, en décubitus dorsal avec un coussin sous la tête : oxygène, couverture, DSA laissé en place, surveillance, heure TU notée.</p>","cref":[{"page":66,"printed":"59","quote":"Le laisser impérativement là où il se trouve, en décubitus dorsal avec un coussin sous la"}],"type":"mcq","input":"radio","options":[{"text":"Le laisser là où il se trouve, en décubitus dorsal avec un coussin sous la tête","correct":true},{"text":"Le mettre en PLS","correct":false},{"text":"Le rasseoir à sa place","correct":false},{"text":"Le déplacer au galley","correct":false}]},{"sid":"c:m-rcp-07","mod":5022,"title":"RCP adulte SANS matériel (1 PNC) : quand fait-on un bilan respiratoire ?","source":"cours","explanation":"<p>Sans matériel : séries de 30 compressions / 2 insufflations (bouche-à-bouche), bilan respiratoire toutes les 5 séries.</p>","cref":[{"page":67,"printed":"60","quote":"Faire un bilan respiratoire toutes les 5 séries"}],"type":"mcq","input":"radio","options":[{"text":"Toutes les 5 séries de 30 compressions / 2 insufflations","correct":true},{"text":"Toutes les 2 minutes","correct":false},{"text":"Après chaque série","correct":false},{"text":"Jamais","correct":false}]},{"sid":"c:m-rcp-08","mod":5022,"title":"Bouche-à-bouche (adulte) : remets les gestes dans l'ordre.","source":"cours","explanation":"<p>Tête basculée, nez pincé, bouche ouverte et menton élevé, inspirer sans excès, insuffler environ 1 s jusqu'au soulèvement. On se redresse pour vérifier l'affaissement, puis on fait la 2e insufflation, les deux en moins de 5 s.</p>","cref":[{"page":67,"printed":"60","quote":"Inspirer sans excès"},{"page":67,"printed":"60","quote":"Insuffler une seconde fois dans les mêmes conditions"}],"type":"order","items":["Basculer la tête du PAX en arrière","Pincer le nez entre le pouce et l'index","Ouvrir légèrement la bouche et maintenir le menton élevé","Inspirer sans excès","Appliquer la bouche largement ouverte autour de celle du PAX","Insuffler lentement jusqu'à ce que la poitrine commence à se soulever","Se redresser et vérifier l'affaissement de la poitrine","Insuffler une seconde fois"]},{"sid":"c:m-enf-01","mod":5022,"title":"RCP de l'enfant (1 à 8 ans) : par quoi commence-t-on ?","source":"cours","explanation":"<p>L'arrêt cardiaque chez l'enfant est le plus souvent d'origine respiratoire : on commence par 5 insufflations initiales, puis rythme 15/2.</p>","cref":[{"page":69,"printed":"62","quote":"Commencer par 5 insufflations initiales"}],"type":"mcq","input":"radio","options":[{"text":"5 insufflations initiales","correct":true},{"text":"30 compressions thoraciques","correct":false},{"text":"15 compressions thoraciques","correct":false},{"text":"La pose du DSA","correct":false}]},{"sid":"c:m-enf-02","mod":5022,"title":"Quel est le rythme de la RCP chez l'enfant ?","source":"cours","explanation":"<p>Enfant : 15 massages / 2 insufflations, bilan respiratoire toutes les 5 séries.</p>","cref":[{"page":69,"printed":"62","quote":"Poursuivre la réanimation sur un rythme de 15 massages / 2 insufflations"}],"type":"mcq","input":"radio","options":[{"text":"15 compressions / 2 insufflations","correct":true},{"text":"30 compressions / 2 insufflations","correct":false},{"text":"5 compressions / 1 insufflation","correct":false},{"text":"15 compressions / 1 insufflation","correct":false}]},{"sid":"c:m-enf-03","mod":5022,"title":"Où place-t-on les électrodes du DSA chez l'enfant ?","source":"cours","explanation":"<p>Le DSA s'utilise comme chez l'adulte (réduire l'intensité du choc si possible), mais une électrode va sur le thorax et l'autre dans le dos, entre les omoplates.</p>","cref":[{"page":69,"printed":"62","quote":"première électrode sera posée sur le thorax, la seconde dans le dos"}],"type":"mcq","input":"radio","options":[{"text":"Une sur le thorax, la seconde dans le dos entre les 2 omoplates","correct":true},{"text":"Comme chez l'adulte","correct":false},{"text":"Les deux dans le dos","correct":false},{"text":"Le DSA n'est pas utilisé chez l'enfant","correct":false}]},{"sid":"c:m-enf-04","mod":5022,"title":"La réanimation « enfant » concerne quel public ?","source":"cours","explanation":"<p>Réanimation de l'enfant : de 1 à 8 ans (moins de 25 kg). Nourrisson : 0 à 1 an.</p>","cref":[{"page":68,"printed":"61","quote":"LA REANIMATION DE L’ENFANT DE 1 A 8 ANS"}],"type":"mcq","input":"radio","options":[{"text":"De 1 à 8 ans (moins de 25 kg)","correct":true},{"text":"De 0 à 1 an","correct":false},{"text":"De 2 à 12 ans","correct":false},{"text":"Moins de 40 kg","correct":false}]},{"sid":"c:m-nrs-01","mod":5022,"title":"Le DSA est utilisé pour réanimer un nourrisson.","source":"cours","explanation":"<p>Faux. Le DSA n'est pas utilisé pour un nourrisson. On commence par 5 insufflations starters, puis 15 compressions pour 2 insufflations.</p>","cref":[{"page":70,"printed":"63","quote":"Le DSA n’est pas utilisé pour un nourrisson"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:m-nrs-02","mod":5022,"title":"Insufflations starters chez le nourrisson : quel volume d'air souffler ?","source":"cours","explanation":"<p>5 insufflations lentes et progressives, bouche englobant la bouche et le nez du bébé, en soufflant uniquement la moitié du volume d'air contenu dans la bouche du PNC.</p>","cref":[{"page":70,"printed":"63","quote":"Souffler uniquement la moitié du volume d’air contenu"}],"type":"mcq","input":"radio","options":[{"text":"Uniquement la moitié du volume d'air contenu dans la bouche du PNC","correct":true},{"text":"Tout le volume d'air de la bouche du PNC","correct":false},{"text":"Un volume équivalent à celui de l'adulte","correct":false},{"text":"Le volume d'une inspiration profonde","correct":false}]},{"sid":"c:m-nrs-03","mod":5022,"title":"Nourrisson réanimé qui respire : à quel débit lui donner de l'oxygène ?","source":"cours","explanation":"<p>Tuyau d'oxygène passé devant le nez en évitant les yeux, débit réglé à 2 L/min. Le bébé est placé en PLS dans les bras du PNC, dos contre lui.</p>","cref":[{"page":71,"printed":"64","quote":"régler le débit à 2l/mn"}],"type":"mcq","input":"radio","options":[{"text":"2 L/min, tuyau passé devant le nez en évitant les yeux","correct":true},{"text":"4 L/min au masque","correct":false},{"text":"6 L/min","correct":false},{"text":"Pas d'oxygène chez le nourrisson","correct":false}]},{"sid":"c:m-nrs-04","mod":5022,"title":"Quelle est la profondeur des compressions chez le nourrisson ?","source":"cours","explanation":"<p>Nourrisson : pulpe de 2 doigts, 1/3 de l'épaisseur du thorax (à peu près 3 cm), 100 à 120/min, 2 insufflations toutes les 15 compressions.</p>","cref":[{"page":71,"printed":"64","quote":"du thorax (à peu près 3 cm)"}],"type":"mcq","input":"radio","options":[{"text":"1/3 de l'épaisseur du thorax (à peu près 3 cm)","correct":true},{"text":"5 à 6 cm","correct":false},{"text":"1/2 de l'épaisseur du thorax","correct":false},{"text":"1 cm","correct":false}]},{"sid":"c:m-nrs-05","mod":5022,"title":"Qui peut autoriser l'arrêt de la réanimation d'un nourrisson ?","source":"cours","explanation":"<p>Seul un médecin à bord ayant présenté sa carte professionnelle, ou un médecin du SAMU par contact radio depuis le poste de pilotage, peut autoriser l'arrêt.</p>","cref":[{"page":71,"printed":"64","quote":"Seul un médecin à bord ayant présenté sa carte professionnelle"}],"type":"mcq","input":"radio","options":[{"text":"Seul un médecin à bord ayant présenté sa carte professionnelle ou un médecin du SAMU par radio","correct":true},{"text":"Le commandant de bord","correct":false},{"text":"Le responsable de cabine","correct":false},{"text":"Les parents","correct":false}]},{"sid":"c:m-tps-01","mod":5023,"title":"Que faut-il vérifier systématiquement dans la trousse de premiers secours ?","source":"cours","explanation":"<p>Vérifier systématiquement la date de péremption des médicaments et matériels stériles, et que leurs contenants ne soient pas endommagés.</p>","cref":[{"page":72,"printed":"65","quote":"La date de péremption des médicaments et des matériels stériles"}],"type":"mcq","input":"checkbox","options":[{"text":"La date de péremption des médicaments et des matériels stériles","correct":true},{"text":"Que les contenants des médicaments et matériels stériles ne soient pas endommagés","correct":true},{"text":"Le nombre exact de chaque médicament","correct":false},{"text":"La présence d'un tensiomètre","correct":false}]},{"sid":"c:m-tps-02","mod":5023,"title":"Avant de proposer un médicament, que doit faire le PNC ?","source":"cours","explanation":"<p>Questionner le PAX (médicaments déjà pris, allergies), proposer un médicament adapté et avoir le réflexe de consulter les notices.</p>","cref":[{"page":72,"printed":"65","quote":"Avoir le réflexe de consulter les notices"}],"type":"mcq","input":"checkbox","options":[{"text":"Demander au PAX s'il a déjà pris des médicaments et s'il n'est pas sujet à des allergies","correct":true},{"text":"Proposer un médicament adapté aux symptômes","correct":true},{"text":"Consulter les notices (posologie, mode d'administration, précautions)","correct":true},{"text":"Doubler la dose pour plus d'efficacité","correct":false}]},{"sid":"c:m-tps-03","mod":5023,"title":"Quelle est la dose maximale de paracétamol par jour ?","source":"cours","explanation":"<p>Paracétamol 500 mg, à partir de 8 ans : 2 comprimés toutes les 4 à 6 h, maximum 3 g par jour.</p>","cref":[{"page":73,"printed":"62 (2ᵉ série)","quote":"Max 3g / jour"}],"type":"mcq","input":"radio","options":[{"text":"3 g par jour","correct":true},{"text":"1 g par jour","correct":false},{"text":"6 g par jour","correct":false},{"text":"500 mg par jour","correct":false}]},{"sid":"c:m-gan-01","mod":5023,"title":"Remets dans l'ordre le retrait des gants.","source":"cours","explanation":"<p>Gant droit retourné, roulé en boule dans la main gauche, puis gant gauche retourné par-dessus la boule. On jette le tout dans un sac à déchets à risque infectieux et on se lave les mains au savon au moins 30 s.</p>","cref":[{"page":75,"printed":"63 (2ᵉ série)","quote":"Former une boule dans la main gauche avec le gant retiré"}],"type":"order","items":["Insérer deux doigts de la main gauche sous le rebord du gant droit","Retourner le gant droit en le retirant","Former une boule dans la main gauche avec le gant retiré","Insérer deux doigts de la main droite sous le gant gauche","Retourner le gant sur la main gauche pour couvrir la boule","Jeter le tout dans un sac pour déchets à risque infectieux","Se laver les mains avec du savon pendant 30 secondes minimum"]},{"sid":"c:m-ce-01","mod":5023,"title":"Corps étranger FICHÉ dans l'œil : que faire ?","source":"cours","explanation":"<p>Masque de repos protégeant les DEUX yeux (le mouvement de l'un entraîne celui de l'autre), ou à défaut un pansement binoculaire non compressif, et consultation d'un ophtalmologiste. Le rinçage concerne le corps étranger mobile.</p>","cref":[{"page":76,"printed":"64 (2ᵉ série)","quote":"Donner un masque de repos protégeant les deux yeux"}],"type":"mcq","input":"radio","options":[{"text":"Donner un masque de repos protégeant les deux yeux et conseiller un ophtalmologiste à l'arrivée","correct":true},{"text":"Rincer l'œil au sérum physiologique jusqu'à disparition de la gêne","correct":false},{"text":"Retirer délicatement le corps étranger avec une compresse","correct":false},{"text":"Couvrir uniquement l'œil blessé","correct":false}]},{"sid":"c:m-ce-02","mod":5023,"title":"Corps étranger MOBILE dans l'œil : comment le traiter ?","source":"cours","explanation":"<p>Mains lavées et gants, tête penchée vers le côté atteint, le PAX tire sur sa paupière, puis rinçage au sérum physiologique jusqu'à disparition de la gêne.</p>","cref":[{"page":76,"printed":"64 (2ᵉ série)","quote":"Rincer l’œil à l’aide d’une ou plusieurs pipettes de sérum physiologique"}],"type":"mcq","input":"radio","options":[{"text":"Rincer l'œil avec une ou plusieurs pipettes de sérum physiologique","correct":true},{"text":"Masque de repos sur les deux yeux","correct":false},{"text":"Le retirer avec une pince","correct":false},{"text":"Ne rien faire et attendre l'arrivée","correct":false}]},{"sid":"c:m-ce-03","mod":5023,"title":"Corps étranger dans le NEZ : que faire ?","source":"cours","explanation":"<p>Ne pas tenter de le retirer ; faire comprimer la narine opposée et moucher. S'il ne sort pas, tête légèrement penchée en avant jusqu'à l'arrivée et consultation ORL.</p>","cref":[{"page":76,"printed":"64 (2ᵉ série)","quote":"Ne pas tenter de retirer le corps étranger"}],"type":"mcq","input":"radio","options":[{"text":"Ne pas tenter de le retirer ; faire comprimer la narine opposée et faire moucher","correct":true},{"text":"Le retirer avec une pince à écharde","correct":false},{"text":"Rincer au sérum physiologique","correct":false},{"text":"Faire pencher la tête en arrière","correct":false}]},{"sid":"c:m-ce-04","mod":5023,"title":"Objet pénétrant dans une plaie grave : que faire ?","source":"cours","explanation":"<p>Ne jamais retirer l'objet pénétrant ; faire un appel médecin et surveiller les paramètres vitaux.</p>","cref":[{"page":76,"printed":"64 (2ᵉ série)","quote":"Ne jamais retirer l’objet pénétrant"}],"type":"mcq","input":"radio","options":[{"text":"Ne jamais le retirer, faire un appel médecin et surveiller les paramètres vitaux","correct":true},{"text":"Le retirer délicatement puis faire un pansement compressif","correct":false},{"text":"Le retirer et poser un garrot","correct":false},{"text":"Le couper au ras de la peau","correct":false}]},{"sid":"c:m-ce-05","mod":5023,"title":"Corps étranger dans l'oreille, non accessible : que faire ?","source":"cours","explanation":"<p>S'il n'est pas accessible, éviter les manœuvres qui pourraient léser le tympan : compresse et sparadrap sur le pavillon, tête légèrement inclinée du côté atteint, ORL dès l'arrivée.</p>","cref":[{"page":76,"printed":"64 (2ᵉ série)","quote":"Poser une compresse maintenue par un Sparadrap sur le pavillon de l’oreille"}],"type":"mcq","input":"radio","options":[{"text":"Compresse maintenue par du sparadrap sur le pavillon, tête inclinée du côté atteint, consulter un ORL","correct":true},{"text":"Le retirer avec une pince","correct":false},{"text":"Rincer l'oreille","correct":false},{"text":"Incliner la tête du côté opposé","correct":false}]},{"sid":"c:m-ban-01","mod":5023,"title":"Associe chaque terme de bandage à sa définition.","source":"cours","explanation":"<p>Chef : extrémité. Globe : partie roulée. Circulaire : tour de bande. Frein : repli de la 1re circulaire recouvert par la 2e. Récurrent : recouvre les extrémités. Huit : projection croisée.</p>","cref":[{"page":77,"printed":"65 (2ᵉ série)","quote":"Globe : partie roulée de la bande"},{"page":77,"printed":"65 (2ᵉ série)","quote":"Huit : projection croisée de la bande"}],"type":"match","pairs":[{"left":"Chef","right":"Extrémité de la bande"},{"left":"Globe","right":"Partie roulée de la bande"},{"left":"Frein","right":"Repli de la pointe de la 1re circulaire recouvert par la 2e"},{"left":"Récurrent","right":"Projection de bande pour recouvrir les extrémités"},{"left":"Huit","right":"Projection croisée de la bande"}]},{"sid":"c:m-ban-02","mod":5023,"title":"Quels sont les principes généraux d'un bandage ?","source":"cours","explanation":"<p>Bijoux ôtés, bande Velpeau adaptée, globe ouvert, début par 2 circulaires avec frein, fin par 2 circulaires avec arrêt. Un bandage ne doit jamais bloquer la circulation.</p>","cref":[{"page":77,"printed":"65 (2ᵉ série)","quote":"Toujours débuter un bandage par 2 circulaires avec frein"}],"type":"mcq","input":"checkbox","options":[{"text":"Ôter les bijoux avant (risque d'œdème)","correct":true},{"text":"Toujours débuter par 2 circulaires avec frein","correct":true},{"text":"Toujours terminer par 2 circulaires avec un arrêt","correct":true},{"text":"Manipuler la bande globe ouvert","correct":true},{"text":"Serrer fort pour bien tenir","correct":false}]},{"sid":"c:m-ban-03","mod":5023,"title":"Bandage occlusif de la main : remets les étapes dans l'ordre.","source":"cours","explanation":"<p>2 circulaires avec frein au poignet, 2 récurrents sur la main, circulaire à l'extrémité des doigts, puis « huit » en épis réguliers des doigts vers le poignet. On termine par 2 circulaires, un rabat et une fixation (épingle ou sparadrap).</p>","cref":[{"page":86,"printed":"74","quote":"Faire 2 récurrents recouvrant entièrement la main"}],"type":"order","items":["Commencer par 2 circulaires au poignet avec frein","Projeter le globe vers les doigts","Faire 2 récurrents recouvrant entièrement la main","Faire une circulaire à l'extrémité des doigts pour maintenir les récurrents","Commencer le 1er « huit » en croisant sur le dessus de la main","Faire des « huit » successifs en épis réguliers des doigts vers le poignet","Terminer par 2 circulaires au poignet","Faire un rabat vers l'intérieur et fixer"]},{"sid":"c:m-pla-01","mod":5023,"title":"Comment nettoie-t-on une plaie superficielle ?","source":"cours","explanation":"<p>Compresse prise par les 4 coins (en parachute), nettoyage du centre vers l'extérieur (en escargot), puis séchage de la même façon avec une nouvelle compresse stérile.</p>","cref":[{"page":78,"printed":"66","quote":"Nettoyer la plaie en commençant par le centre de celle-ci et en allant vers l’extérieur"}],"type":"mcq","input":"radio","options":[{"text":"Du centre vers l'extérieur (en escargot), compresse prise par les 4 coins","correct":true},{"text":"De l'extérieur vers le centre","correct":false},{"text":"De haut en bas","correct":false},{"text":"En frottant fortement","correct":false}]},{"sid":"c:m-pla-02","mod":5023,"title":"Plaie superficielle : quel matériel commun réunir sur le plateau ?","source":"cours","explanation":"<p>Matériel commun : gants, compresses stériles (3 paquets minimum), sac vomitoire (poubelle), antiseptique cutané. Puis selon le cas : pansement adhésif, bandes, ou écharpe pour l'emballage.</p>","cref":[{"page":78,"printed":"66","quote":"Compresses stériles (3 paquets minimum)"}],"type":"mcq","input":"checkbox","options":[{"text":"Une paire de gants à porter dès le début du soin","correct":true},{"text":"Compresses stériles (3 paquets minimum)","correct":true},{"text":"Sac vomitoire (poubelle)","correct":true},{"text":"Antiseptique cutané","correct":true},{"text":"Tulle gras","correct":false}]},{"sid":"c:m-pla-03","mod":5023,"title":"Plaie superficielle : remets dans l'ordre le soin.","source":"cours","explanation":"<p>Gants, antiseptique, nettoyage puis séchage en escargot, protection de la plaie. On retire les gants selon les règles d'hygiène, puis on demande si le PAX est à jour de son vaccin antitétanique.</p>","cref":[{"page":78,"printed":"66","quote":"Préciser que vos mains sont lavées et le plateau désinfecté"},{"page":78,"printed":"66","quote":"Verser sur les compresses quelques gouttes d’antiseptique"},{"page":78,"printed":"66","quote":"Nettoyer la plaie en commençant par le centre de celle-ci"},{"page":79,"printed":"67","quote":"Demander au PAX s’il est à jour de sa vaccination antitétanique"}],"type":"order","items":["Préciser que vos mains sont lavées et le plateau désinfecté, mettre les gants","Verser quelques gouttes d'antiseptique sur les compresses","Nettoyer la plaie du centre vers l'extérieur (en escargot)","Sécher délicatement avec une nouvelle compresse stérile, en escargot","Protéger la plaie (pansement adhésif, bandage ou emballage)","Retirer ses gants et se laver les mains","Demander au PAX s'il est à jour de sa vaccination antitétanique"]},{"sid":"c:m-pla-04","mod":5023,"title":"Quelles sont les 3 possibilités pour protéger une plaie superficielle ?","source":"cours","explanation":"<p>Selon l'étendue et la profondeur : pansement adhésif, bandage occlusif ou simple (le plus fréquent à l'examen), ou emballage.</p>","cref":[{"page":78,"printed":"66","quote":"Bandage occlusif ou simple (le plus fréquent à l’examen)"}],"type":"mcq","input":"radio","options":[{"text":"Pansement adhésif, bandage occlusif ou simple, emballage","correct":true},{"text":"Pansement compressif, garrot, emballage","correct":false},{"text":"Tulle gras, bandage, écharpe","correct":false},{"text":"Sparadrap seul, compresse, emballage","correct":false}]},{"sid":"c:m-hem-01","mod":5023,"title":"Hémorragie externe : quel est le premier geste ?","source":"cours","explanation":"<p>L'arrêt d'une hémorragie est le préalable à tout autre geste d'urgence. On demande au PAX de dégager la plaie et de faire une compression manuelle (main protégée), puis de s'allonger.</p>","cref":[{"page":80,"printed":"68","quote":"L’arrêt d’une hémorragie est le préalable à tout autre geste d’urgence"}],"type":"mcq","input":"radio","options":[{"text":"Faire faire une compression manuelle sur la plaie","correct":true},{"text":"Poser un garrot","correct":false},{"text":"Nettoyer la plaie","correct":false},{"text":"Allonger le PAX en PLS","correct":false}]},{"sid":"c:m-hem-02","mod":5023,"title":"À bord, une compression manuelle seule suffit à traiter une hémorragie externe.","source":"cours","explanation":"<p>Faux. À bord, une compression manuelle seule ne peut être envisagée (turbulences…) : dès que possible, on prend le relais avec un pansement compressif.</p>","cref":[{"page":80,"printed":"68","quote":"Dès que possible, prendre le relais avec un pansement compressif"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:m-hem-03","mod":5023,"title":"Pansement compressif : quel matériel réunir ?","source":"cours","explanation":"<p>Gants, compresses stériles, une bande de 5 cm (le « bouchon »), 2 bandes de 7 à 10 cm, et 2 épingles (facultatives si double nœud efficace).</p>","cref":[{"page":81,"printed":"69","quote":"2 bandes Velpeau de 7 à 10 cm selon l’étendue de la plaie"}],"type":"mcq","input":"checkbox","options":[{"text":"1 paire de gants","correct":true},{"text":"Pochettes de compresses stériles","correct":true},{"text":"Une bande Velpeau de 5 cm (le « bouchon »)","correct":true},{"text":"2 bandes Velpeau de 7 à 10 cm","correct":true},{"text":"Du tulle gras","correct":false}]},{"sid":"c:m-hem-04","mod":5023,"title":"Pour un pansement compressif, on se lave d'abord les mains avant de mettre les gants.","source":"cours","explanation":"<p>Faux. Exceptionnellement, on ne se lave pas les mains pour ne pas retarder le traitement, mais on met des gants avant de commencer.</p>","cref":[{"page":81,"printed":"69","quote":"Exceptionnellement, ne pas se laver les mains pour ne pas retarder le traitement"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:m-hem-05","mod":5023,"title":"L'hémorragie persiste malgré le pansement compressif : remets dans l'ordre.","source":"cours","explanation":"<p>On ne défait jamais un pansement compressif : on refait des circulaires par-dessus. En cas d'échec, on reprend la compression manuelle par-dessus et on la maintient jusqu'aux secours.</p>","cref":[{"page":82,"printed":"70","quote":"Ne jamais défaire un pansement compressif"}],"type":"order","items":["Laisser le premier bandage en place et refaire des circulaires par-dessus avec une autre bande","En cas d'échec, reprendre la compression manuelle par-dessus les pansements","Maintenir la compression jusqu'à l'arrivée des secours"]},{"sid":"c:m-gar-01","mod":5023,"title":"Où place-t-on un garrot ?","source":"cours","explanation":"<p>Entre la plaie et le cœur, à quelques centimètres au-dessus (un travers de main, soit 5 à 7 cm), jamais sur une articulation.</p>","cref":[{"page":82,"printed":"70","quote":"Le garrot se place entre la plaie et le cœur"}],"type":"mcq","input":"radio","options":[{"text":"Entre la plaie et le cœur, un travers de main au-dessus de la plaie, jamais sur une articulation","correct":true},{"text":"Directement sur la plaie","correct":false},{"text":"Sous la plaie","correct":false},{"text":"Sur l'articulation la plus proche","correct":false}]},{"sid":"c:m-gar-02","mod":5023,"title":"Dans quels cas utilise-t-on un garrot (en dernier recours) ?","source":"cours","explanation":"<p>Le garrot est exceptionnel : pansement compressif impossible ou inefficace (corps étranger fiché, fracture ouverte), autres blessés en urgence vitale, ou membre sectionné ou arraché.</p>","cref":[{"page":82,"printed":"70","quote":"S’il y a d’autres blessés en urgence vitale"}],"type":"mcq","input":"checkbox","options":[{"text":"Pansement compressif impossible ou inefficace après la 2e compression manuelle","correct":true},{"text":"S'il y a d'autres blessés en urgence vitale","correct":true},{"text":"Membre sectionné ou arraché avec hémorragie incontrôlable","correct":true},{"text":"Toute plaie qui saigne","correct":false}]},{"sid":"c:m-gar-03","mod":5023,"title":"Garrot : quelles précautions ?","source":"cours","explanation":"<p>Heure de pose notée en TU (heures et minutes) bien visible sur le PAX, garrot jamais recouvert, jamais desserré : seul un médecin est autorisé à l'enlever.</p>","cref":[{"page":83,"printed":"71","quote":"Seul un médecin est autorisé à l’enlever"}],"type":"mcq","input":"checkbox","options":[{"text":"Noter l'heure de pose en heure TU (heure et minutes), de façon apparente sur le PAX","correct":true},{"text":"Le garrot doit rester toujours visible","correct":true},{"text":"Ne jamais le desserrer ; seul un médecin peut l'enlever","correct":true},{"text":"Le desserrer toutes les 20 minutes","correct":false}]},{"sid":"c:m-gar-04","mod":5023,"title":"Quelle méthode de garrot est la plus efficace ?","source":"cours","explanation":"<p>La méthode du garrot tourniquet (lien de toile d'environ 1,50 m + bâton) est la plus efficace.</p>","cref":[{"page":82,"printed":"70","quote":"la méthode du garrot tourniquet est la plus efficace"}],"type":"mcq","input":"radio","options":[{"text":"Le garrot tourniquet","correct":true},{"text":"Le garrot simple","correct":false},{"text":"Le pansement compressif","correct":false},{"text":"Le garrot élastique","correct":false}]},{"sid":"c:m-bru-01","mod":5023,"title":"Pendant combien de temps refroidit-on une brûlure de la main à l'eau minérale ?","source":"cours","explanation":"<p>Eau minérale versée doucement sur une compresse posée sur la brûlure pendant au moins 10 minutes, sans que le goulot touche la compresse.</p>","cref":[{"page":85,"printed":"73","quote":"Faire couler doucement de l’eau minérale sur la compresse pendant au moins 10"}],"type":"mcq","input":"radio","options":[{"text":"Au moins 10 minutes","correct":true},{"text":"Au moins 2 minutes","correct":false},{"text":"30 secondes","correct":false},{"text":"Au moins 30 minutes","correct":false}]},{"sid":"c:m-bru-02","mod":5023,"title":"Brûlure du 2nd degré de la main : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Gants, eau minérale 1,5 L, sac vomitoire, compresses stériles, tulle gras, 3 bandes stériles, sparadrap, 2 comprimés de paracétamol et un verre d'eau.</p>","cref":[{"page":85,"printed":"73","quote":"1 bouteille d’eau minérale (1,5L)"}],"type":"mcq","input":"checkbox","options":[{"text":"1 bouteille d'eau minérale (1,5 L) et 1 sac vomitoire","correct":true},{"text":"Compresses stériles et tulle gras","correct":true},{"text":"3 bandes stériles (7 ou 10 cm) et sparadrap","correct":true},{"text":"2 comprimés de paracétamol et un verre d'eau","correct":true},{"text":"Un garrot","correct":false}]},{"sid":"c:m-bru-03","mod":5023,"title":"Brûlure de la main : remets dans l'ordre le soin.","source":"cours","explanation":"<p>Main au-dessus du sac, compresse, eau au moins 10 min, séchage en tamponnant, tulle gras (films retirés), compresse et bandage occlusif non compressif. À la fin : antalgique et vaccin antitétanique.</p>","cref":[{"page":85,"printed":"73","quote":"Proposer l’antalgique avec un verre d’eau, à la fin du soin"}],"type":"order","items":["Poser le sac vomitoire debout et faire placer la main au-dessus","Poser délicatement une compresse stérile sur la brûlure","Faire couler l'eau minérale sur la compresse pendant au moins 10 minutes","Enlever la compresse et assécher en tamponnant sans léser les phlyctènes","Déposer le tulle gras sur la brûlure","Recouvrir d'une compresse stérile et faire un bandage occlusif non compressif","Proposer l'antalgique avec un verre d'eau","Demander si le PAX est à jour de son vaccin antitétanique"]},{"sid":"c:m-bru-04","mod":5023,"title":"Dans quels cas une brûlure est-elle grave ?","source":"cours","explanation":"<p>Grave : cloques au-delà de la moitié de la paume, destruction profonde, localisation au visage, au cou, aux mains, aux articulations ou aux orifices naturels, rougeur étendue chez l'enfant, origine électrique ou chimique.</p>","cref":[{"page":84,"printed":"72","quote":"D’une brûlure d’origine électrique ou chimique"}],"type":"mcq","input":"checkbox","options":[{"text":"Cloque(s) d'une surface supérieure à la moitié de la paume de la victime","correct":true},{"text":"Localisation au visage, au cou, aux mains, aux articulations","correct":true},{"text":"Origine électrique ou chimique","correct":true},{"text":"Rougeur étendue de la peau chez l'enfant","correct":true},{"text":"Petite rougeur chez l'adulte","correct":false}]},{"sid":"c:m-bru-05","mod":5023,"title":"Brûlure électrique ou chimique : quelle est la première règle ?","source":"cours","explanation":"<p>Ne pas toucher la personne avant la suppression du risque, arroser la zone brûlée, ne jamais faire vomir ni boire en cas d'ingestion, contacter le SAMU via le cockpit.</p>","cref":[{"page":87,"printed":"75","quote":"Ne pas toucher la personne atteinte avant la suppression du risque"}],"type":"mcq","input":"radio","options":[{"text":"Ne pas toucher la personne avant la suppression du risque","correct":true},{"text":"La faire vomir en cas d'ingestion","correct":false},{"text":"Appliquer du tulle gras immédiatement","correct":false},{"text":"Lui donner à boire","correct":false}]},{"sid":"c:m-bru-06","mod":5023,"title":"Après le soin d'une brûlure de la main, comment installer le passager ?","source":"cours","explanation":"<p>On fait déplacer le passager de sorte que sa main brûlée se trouve côté hublot, pour éviter le suraccident.</p>","cref":[{"page":85,"printed":"73","quote":"Faire déplacer le sujet de sorte que sa main brûlée se trouve côté hublot pour éviter le"}],"type":"mcq","input":"radio","options":[{"text":"Main brûlée côté hublot, pour éviter le suraccident","correct":true},{"text":"Main brûlée côté allée","correct":false},{"text":"Allongé au sol","correct":false},{"text":"Debout au galley","correct":false}]},{"sid":"c:m-emb-01","mod":5023,"title":"Quels sont les principes de base des emballages ?","source":"cours","explanation":"<p>Mains lavées et gants, pas de nœud sur la blessure, base toujours posée sur la partie à protéger.</p>","cref":[{"page":87,"printed":"75","quote":"La base est toujours posée sur la partie à protéger"}],"type":"mcq","input":"checkbox","options":[{"text":"Se laver les mains et porter des gants","correct":true},{"text":"Ne pas faire de nœud sur la blessure","correct":true},{"text":"La base est toujours posée sur la partie à protéger","correct":true},{"text":"Toujours serrer fortement le triangle","correct":false}]},{"sid":"c:m-emb-02","mod":5023,"title":"Emballage de la main : remets les étapes dans l'ordre.","source":"cours","explanation":"<p>Tablette abaissée, bijoux enlevés, triangle sommet vers les doigts, sommet rabattu sur le dos de la main, chefs croisés et noués autour du poignet.</p>","cref":[{"page":88,"printed":"76","quote":"Rabattre le sommet sur le dos de la main"}],"type":"order","items":["Abaisser la tablette","Enlever les bijoux","Poser le triangle sur la tablette, sommet vers les doigts","Rabattre le sommet sur le dos de la main","Croiser les 2 chefs et les nouer autour du poignet"]},{"sid":"c:m-emb-03","mod":5023,"title":"Plaie du front : comment poser le triangle ?","source":"cours","explanation":"<p>Plaie du front : base sur le front, sommet vers la nuque, chefs noués sur la nuque. Plaie de la nuque : l'inverse, chefs noués sur le front.</p>","cref":[{"page":87,"printed":"75","quote":"Poser le triangle sur la tête, base sur le front, sommet vers la nuque"}],"type":"mcq","input":"radio","options":[{"text":"Base sur le front, sommet vers la nuque ; nouer les chefs sur la nuque","correct":true},{"text":"Base sur la nuque, sommet vers le front","correct":false},{"text":"Base sur le front ; nouer les chefs sur le front","correct":false},{"text":"Sommet sur le front","correct":false}]},{"sid":"c:m-fra-01","mod":5024,"title":"Quels signes recherche-t-on, en comparaison avec l'autre membre, pour suspecter une fracture fermée ?","source":"cours","explanation":"<p>En comparant avec l'autre membre : œdème, ecchymose, déformation, impotence fonctionnelle totale, douleur exquise à la palpation (trait de fracture), absence de plaie.</p>","cref":[{"page":91,"printed":"79","quote":"Une douleur exquise à la palpation douce = trait de fracture"}],"type":"mcq","input":"checkbox","options":[{"text":"Œdème, ecchymose, déformation","correct":true},{"text":"Impotence fonctionnelle totale","correct":true},{"text":"Douleur exquise à la palpation douce (trait de fracture)","correct":true},{"text":"L'absence de plaie","correct":true},{"text":"Saignement abondant","correct":false}]},{"sid":"c:m-fra-02","mod":5024,"title":"Quel est le but de l'immobilisation d'un membre fracturé ?","source":"cours","explanation":"<p>L'immobilisation bloque les articulations situées au-dessus et au-dessous du foyer de fracture, pour ne permettre aucun mouvement.</p>","cref":[{"page":90,"printed":"78","quote":"L’immobilisation d’un membre a pour but de bloquer les articulations sus et sous"}],"type":"mcq","input":"radio","options":[{"text":"Bloquer les articulations sus et sous-jacentes à la fracture","correct":true},{"text":"Remettre l'os en place","correct":false},{"text":"Comprimer le trait de fracture","correct":false},{"text":"Réchauffer le membre","correct":false}]},{"sid":"c:m-fra-03","mod":5024,"title":"Après l'immobilisation d'une fracture, que doit vérifier le PNC ?","source":"cours","explanation":"<p>Efficacité de l'attelle, extrémités du membre, état général, avis médical dès que possible et installation pour éviter le suraccident.</p>","cref":[{"page":90,"printed":"78","quote":"L’efficacité de l’attelle (contention du membre et blocage des articulations)"}],"type":"mcq","input":"checkbox","options":[{"text":"L'efficacité de l'attelle","correct":true},{"text":"Les extrémités du membre (signes de compression, complications)","correct":true},{"text":"L'état général du PAX","correct":true},{"text":"Demander un avis médical dès que possible","correct":true},{"text":"Retirer l'attelle au bout de 15 minutes","correct":false}]},{"sid":"c:m-fra-04","mod":5024,"title":"On peut placer un lien sur le trait de fracture si l'attelle tient mieux ainsi.","source":"cours","explanation":"<p>Faux. Ne pas positionner de lien sur le trait de fracture.</p>","cref":[{"page":90,"printed":"78","quote":"Ne pas positionner de lien sur le trait de fracture"}],"type":"truefalse","options":[{"text":"Vrai","correct":false},{"text":"Faux","correct":true}]},{"sid":"c:m-fra-05","mod":5024,"title":"Quel matériel est utilisé à l'examen pour réaliser les attelles ?","source":"cours","explanation":"<p>Idéalement des attelles thermoformées ; à défaut du matériel de substitution (bouteilles, revues, couvertures). Pour l'examen : des revues et des couvertures.</p>","cref":[{"page":90,"printed":"78","quote":"Pour l’examen seront utilisées"}],"type":"mcq","input":"radio","options":[{"text":"Des revues et des couvertures","correct":true},{"text":"Des attelles thermoformées","correct":false},{"text":"Des bouteilles d'eau compressées","correct":false},{"text":"Des planches de bois","correct":false}]},{"sid":"c:m-fra-06","mod":5024,"title":"Fracture fermée du doigt : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Doigt : paracétamol + verre d'eau, 1 compresse non stérile, couteau, cuillère ou stylo (si attelle rigide), 2 bandes Velpeau de 5 cm, sparadrap.</p>","cref":[{"page":91,"printed":"79","quote":"2 bandes Velpeau (5cm)"}],"type":"mcq","input":"checkbox","options":[{"text":"2 comprimés de paracétamol et un verre d'eau","correct":true},{"text":"1 compresse non stérile","correct":true},{"text":"2 bandes Velpeau (5 cm)","correct":true},{"text":"Sparadrap","correct":true},{"text":"1 revue et 2 écharpes","correct":false}]},{"sid":"c:m-fra-07","mod":5024,"title":"Fracture du doigt, première méthode : qu'est-ce qui sert d'attelle ?","source":"cours","explanation":"<p>Première méthode : le doigt contigu sert d'attelle, avec une compresse glissée entre les 2 doigts. Deuxième méthode : attelle rigide (couteau, cuillère, stylo).</p>","cref":[{"page":91,"printed":"79","quote":"Première méthode d’immobilisation : le doigt contigu sert d’attelle"}],"type":"mcq","input":"radio","options":[{"text":"Le doigt contigu (sain), avec une compresse entre les 2 doigts","correct":true},{"text":"Une revue pliée","correct":false},{"text":"Une bande de 10 cm","correct":false},{"text":"Une écharpe","correct":false}]},{"sid":"c:m-fra-08","mod":5024,"title":"Fracture fermée de la main : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Main : paracétamol + verre d'eau, 1 revue pliée, 1 écharpe ou linge pour protéger l'attelle, 2 bandes de 7 cm, épingle ou sparadrap, écharpe facultative.</p>","cref":[{"page":93,"printed":"81","quote":"1 revue (pliée afin d’obtenir un support rigide)"}],"type":"mcq","input":"checkbox","options":[{"text":"2 comprimés de paracétamol avec un verre d'eau","correct":true},{"text":"1 revue pliée","correct":true},{"text":"1 écharpe ou linge pour protéger l'attelle","correct":true},{"text":"2 bandes de 7 cm","correct":true},{"text":"3 liens","correct":false}]},{"sid":"c:m-fra-09","mod":5024,"title":"Fracture fermée du poignet : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Poignet : paracétamol + verre d'eau, 1 revue, 2 écharpes, 2 bandes de 10 cm, coton, sparadrap.</p>","cref":[{"page":94,"printed":"82","quote":"2 bandes de 10 cm"}],"type":"mcq","input":"checkbox","options":[{"text":"2 comprimés de paracétamol avec un verre d'eau","correct":true},{"text":"1 revue et 2 écharpes","correct":true},{"text":"2 bandes de 10 cm","correct":true},{"text":"Du coton et du sparadrap","correct":true},{"text":"3 liens","correct":false}]},{"sid":"c:m-fra-10","mod":5024,"title":"Fracture fermée de l'avant-bras : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Avant-bras : 1 ou 2 revue(s), 3 liens, coton, 2 écharpes triangulaires, paracétamol + verre d'eau, sparadrap.</p>","cref":[{"page":96,"printed":"84","quote":"1 ou 2 revue(s)"}],"type":"mcq","input":"checkbox","options":[{"text":"1 ou 2 revue(s)","correct":true},{"text":"3 liens","correct":true},{"text":"Coton et 2 écharpes triangulaires","correct":true},{"text":"2 comprimés de paracétamol avec un verre d'eau, sparadrap","correct":true},{"text":"2 bandes de 5 cm","correct":false}]},{"sid":"c:m-fra-11","mod":5024,"title":"Fracture de l'avant-bras : remets dans l'ordre la fixation des 3 liens.","source":"cours","explanation":"<p>Liens attachés sur la gouttière, à l'extérieur, en évitant le trait de fracture : 1er au poignet, 2e au coude, 3e sous le pouce (le pouce repose sur le lien).</p>","cref":[{"page":97,"printed":"85","quote":"Le 1er lien au milieu au niveau du poignet"}],"type":"order","items":["1er lien au milieu, au niveau du poignet","2e lien au niveau du coude","3e lien sous le pouce"]},{"sid":"c:m-fra-12","mod":5024,"title":"Après l'attelle d'une fracture du poignet ou de l'avant-bras, que faut-il obligatoirement mettre en place ?","source":"cours","explanation":"<p>Mettre obligatoirement en place une écharpe simple pour bloquer l'articulation sus-jacente et positionner le membre en déclive.</p>","cref":[{"page":95,"printed":"83","quote":"Mettre obligatoirement en place une écharpe simple pour bloquer l’articulation"}],"type":"mcq","input":"radio","options":[{"text":"Une écharpe simple pour bloquer l'articulation sus-jacente et positionner le membre en déclive","correct":true},{"text":"Une contre-écharpe","correct":false},{"text":"Une écharpe oblique","correct":false},{"text":"Rien de plus","correct":false}]},{"sid":"c:m-fra-13","mod":5024,"title":"Règle de l'écharpe : comment immobilise-t-on le membre ?","source":"cours","explanation":"<p>Le membre est toujours immobilisé la main plus haute que le coude (déclive), pour favoriser la circulation de retour, en laissant si possible le bout des doigts apparent.</p>","cref":[{"page":98,"printed":"86","quote":"Le membre doit toujours être immobilisé la main plus haute que le coude (déclive)"}],"type":"mcq","input":"radio","options":[{"text":"Main plus haute que le coude (déclive), pour favoriser la circulation de retour","correct":true},{"text":"Main plus basse que le coude","correct":false},{"text":"Bras tendu le long du corps","correct":false},{"text":"Coude plus haut que l'épaule","correct":false}]},{"sid":"c:m-fra-14","mod":5024,"title":"Fracture fermée du bras : quelle immobilisation ?","source":"cours","explanation":"<p>Bras : écharpe simple (qui bloque le coude, pointe attachée avec une épingle) + contre-écharpe (qui plaque l'humérus contre la cage thoracique).</p>","cref":[{"page":99,"printed":"87","quote":"Fracture fermée du bras : écharpe simple"}],"type":"mcq","input":"radio","options":[{"text":"Écharpe simple + contre-écharpe","correct":true},{"text":"Écharpe oblique","correct":false},{"text":"Attelle en gouttière + 3 liens","correct":false},{"text":"Attelle en étrier","correct":false}]},{"sid":"c:m-fra-15","mod":5024,"title":"Luxation d'épaule ou fracture de la clavicule : quelle immobilisation ?","source":"cours","explanation":"<p>Écharpe oblique, après avoir rembourré le creux axillaire (bande, couverture ou 2e écharpe roulée) en respectant la déformation.</p>","cref":[{"page":100,"printed":"88","quote":"Luxation d’épaule ou fracture de la clavicule"},{"page":101,"printed":"89","quote":"Faire une écharpe oblique"}],"type":"mcq","input":"radio","options":[{"text":"Écharpe oblique, creux axillaire rembourré","correct":true},{"text":"Écharpe simple + contre-écharpe","correct":false},{"text":"Attelle en gouttière","correct":false},{"text":"Remettre l'épaule en place","correct":false}]},{"sid":"c:m-fra-16","mod":5024,"title":"Associe chaque écharpe improvisée à sa technique.","source":"cours","explanation":"<p>Revers : bord inférieur du vêtement replié et boutonné. Napoléon : main dans l'échancrure ou entre 2 boutons. Sautoir : main sur une cravate ou un foulard noué en collier.</p>","cref":[{"page":102,"printed":"90","quote":"La main est glissée dans l’échancrure du vêtement ou entre 2 boutons"}],"type":"match","pairs":[{"left":"Méthode « revers »","right":"Bord inférieur du vêtement replié et fixé par un bouton"},{"left":"Méthode « Napoléon »","right":"Main glissée dans l'échancrure du vêtement"},{"left":"Méthode « sautoir »","right":"Main sur une cravate ou un foulard noué en collier"}]},{"sid":"c:m-fra-17","mod":5024,"title":"Fracture fermée de la cheville : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Cheville : paracétamol, 4 magazines, 1 couverture, sparadrap, coton, 2 liens. La jambe demande 6 magazines, 2 couvertures et 3 liens.</p>","cref":[{"page":103,"printed":"91","quote":"4 magazines"}],"type":"mcq","input":"checkbox","options":[{"text":"2 comprimés de paracétamol","correct":true},{"text":"4 magazines et 1 couverture","correct":true},{"text":"Sparadrap et coton","correct":true},{"text":"2 liens","correct":true},{"text":"6 magazines et 2 couvertures","correct":false}]},{"sid":"c:m-fra-18","mod":5024,"title":"Fracture fermée de la jambe : quel matériel sur le plateau ?","source":"cours","explanation":"<p>Jambe : paracétamol, 6 magazines, 2 couvertures, sparadrap, coton, 3 liens.</p>","cref":[{"page":105,"printed":"93","quote":"6 magazines"}],"type":"mcq","input":"checkbox","options":[{"text":"2 comprimés de paracétamol","correct":true},{"text":"6 magazines et 2 couvertures","correct":true},{"text":"Sparadrap et coton","correct":true},{"text":"3 liens","correct":true},{"text":"4 magazines et 1 couverture","correct":false}]},{"sid":"c:m-fra-19","mod":5024,"title":"Fracture de la cheville : remets dans l'ordre la réalisation de l'attelle en étrier.","source":"cours","explanation":"<p>Revues imbriquées (2×2), roulées dans une couverture, liens glissés dans les creux naturels, étrier placé sans redresser le pied. Nœuds provisoires (mollet puis au-dessus de la fracture), puis serrage définitif avec du coton.</p>","cref":[{"page":104,"printed":"92","quote":"Rouler et serrer les revues dans une couverture pour obtenir une attelle de la longueur"}],"type":"order","items":["Imbriquer les revues tête-bêche (2×2 revues de part et d'autre de l'espace pour la plante du pied)","Rouler et serrer les revues dans une couverture","Glisser les liens dans les creux naturels sans mobiliser la jambe","Placer l'étrier de part et d'autre de la jambe, sans redresser le pied","Attacher par un nœud provisoire : 1er lien au mollet, 2e au-dessus de la fracture","Resserrer définitivement les liens en protégeant avec du coton"]},{"sid":"c:m-fra-20","mod":5024,"title":"Fracture de la jambe immobilisée : comment installer le PAX ?","source":"cours","explanation":"<p>La jambe immobilisée ne doit pas être côté allée ; on la surélève (dossier rabattu du siège devant, ou sièges voisins) pour favoriser la circulation, et on conseille une radio à l'arrivée.</p>","cref":[{"page":104,"printed":"92","quote":"La jambe immobilisée ne doit pas"}],"type":"mcq","input":"radio","options":[{"text":"Jambe immobilisée surélevée, jamais côté allée","correct":true},{"text":"Jambe immobilisée côté allée pour pouvoir la surveiller","correct":false},{"text":"Allongé au sol jusqu'à l'arrivée","correct":false},{"text":"Jambe pendante pour soulager","correct":false}]},{"sid":"c:m-fra-21","mod":5024,"title":"Que surveille-t-on aux extrémités d'un avant-bras immobilisé (examen comparatif) ?","source":"cours","explanation":"<p>Avant-bras : couleur, chaleur, sensibilité, motricité et présence du pouls radial.</p>","cref":[{"page":97,"printed":"85","quote":"La présence du pouls radial"}],"type":"mcq","input":"checkbox","options":[{"text":"La couleur et la chaleur","correct":true},{"text":"La sensibilité et la motricité","correct":true},{"text":"La présence du pouls radial","correct":true},{"text":"La tension artérielle du bras blessé","correct":false}]},{"sid":"c:m-fra-22","mod":5024,"title":"Bandage de la cheville : remets les étapes dans l'ordre.","source":"cours","explanation":"<p>2 circulaires avec frein autour du talon, globe vers les orteils, passage sous les orteils, « huit » en épis des orteils vers la cheville, puis 2 circulaires et rabat fixé au sparadrap.</p>","cref":[{"page":107,"printed":"95","quote":"Commencer par 2 circulaires avec frein autour du talon"}],"type":"order","items":["Commencer par 2 circulaires avec frein autour du talon","Projeter le globe vers les orteils","Passer sous les orteils","Faire des « huit » successifs en épis réguliers des orteils vers la cheville","Terminer par 2 circulaires autour de la cheville et faire un rabat"]}]};
